def column_name(index: int) -> str:
    name = ""
    while index:
        index, remainder = divmod(index - 1, 26)
        name = chr(65 + remainder) + name
    return name


def sanitize_sheet_name(name: str) -> str:
    cleaned = re.sub(r"[\[\]:*?/\\]", "_", str(name).strip()) or "Sheet"
    return cleaned[:31]


def build_xlsx(path: str | Path, worksheets: list[tuple[str, list[list[str]]]]):
    sheet_names = []
    used = set()
    for index, (name, _rows) in enumerate(worksheets, start=1):
        base = sanitize_sheet_name(name)
        sheet_name = base
        suffix = 1
        while sheet_name in used:
            tail = f"_{suffix}"
            sheet_name = f"{base[:31 - len(tail)]}{tail}"
            suffix += 1
        used.add(sheet_name)
        sheet_names.append(sheet_name)

    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as xlsx:
        content_types = [
            '<?xml version="1.0" encoding="UTF-8"?>',
            '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">',
            '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>',
            '<Default Extension="xml" ContentType="application/xml"/>',
            '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>',
            '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>',
        ]
        for index in range(1, len(worksheets) + 1):
            content_types.append(
                f'<Override PartName="/xl/worksheets/sheet{index}.xml" '
                'ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
            )
        content_types.append("</Types>")
        xlsx.writestr("[Content_Types].xml", "".join(content_types))
        xlsx.writestr(
            "_rels/.rels",
            '<?xml version="1.0" encoding="UTF-8"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
            "</Relationships>",
        )
        workbook = [
            '<?xml version="1.0" encoding="UTF-8"?>',
            '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
            'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>',
        ]
        workbook_rels = [
            '<?xml version="1.0" encoding="UTF-8"?>',
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">',
        ]
        for index, sheet_name in enumerate(sheet_names, start=1):
            escaped_sheet_name = escape(sheet_name, {'"': "&quot;"})
            workbook.append(f'<sheet name="{escaped_sheet_name}" sheetId="{index}" r:id="rId{index}"/>')
            workbook_rels.append(
                f'<Relationship Id="rId{index}" '
                'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" '
                f'Target="worksheets/sheet{index}.xml"/>'
            )
        workbook.append("</sheets></workbook>")
        workbook_rels.append("</Relationships>")
        xlsx.writestr("xl/workbook.xml", "".join(workbook))
        xlsx.writestr("xl/_rels/workbook.xml.rels", "".join(workbook_rels))
        xlsx.writestr(
            "xl/styles.xml",
            '<?xml version="1.0" encoding="UTF-8"?>'
            '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
            '<fonts count="1"><font><sz val="11"/><name val="Microsoft YaHei"/></font></fonts>'
            '<fills count="1"><fill><patternFill patternType="none"/></fill></fills>'
            '<borders count="1"><border/></borders>'
            '<cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="1"><xf/></cellXfs>'
            "</styleSheet>",
        )
        for sheet_index, (_sheet_name, rows) in enumerate(worksheets, start=1):
            parts = [
                '<?xml version="1.0" encoding="UTF-8"?>',
                '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>',
            ]
            for row_index, row in enumerate(rows, start=1):
                parts.append(f'<row r="{row_index}">')
                for col_index, cell in enumerate(row, start=1):
                    ref = f"{column_name(col_index)}{row_index}"
                    value = escape("" if cell is None else str(cell))
                    parts.append(f'<c r="{ref}" t="inlineStr"><is><t xml:space="preserve">{value}</t></is></c>')
                parts.append("</row>")
            parts.append("</sheetData></worksheet>")
            xlsx.writestr(f"xl/worksheets/sheet{sheet_index}.xml", "".join(parts))


def read_xlsx(path: str | Path) -> list[tuple[str, list[list[str]]]]:
    ns = {
        "x": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
        "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
        "rel": "http://schemas.openxmlformats.org/package/2006/relationships",
    }
    with zipfile.ZipFile(path) as xlsx:
        shared_strings = []
        if "xl/sharedStrings.xml" in xlsx.namelist():
            root = ET.fromstring(xlsx.read("xl/sharedStrings.xml"))
            for item in root.findall("x:si", ns):
                shared_strings.append("".join(text.text or "" for text in item.findall(".//x:t", ns)))

        workbook = ET.fromstring(xlsx.read("xl/workbook.xml"))
        rel_root = ET.fromstring(xlsx.read("xl/_rels/workbook.xml.rels"))
        rels = {rel.attrib["Id"]: rel.attrib["Target"] for rel in rel_root.findall("rel:Relationship", ns)}
        worksheets = []
        for sheet in workbook.findall("x:sheets/x:sheet", ns):
            sheet_name = sheet.attrib.get("name", "Sheet")
            rel_id = sheet.attrib.get(f"{{{ns['r']}}}id")
            target = rels.get(rel_id, "")
            if not target:
                continue
            sheet_path = target.lstrip("/")
            if not sheet_path.startswith("xl/"):
                sheet_path = f"xl/{sheet_path}"
            sheet_root = ET.fromstring(xlsx.read(sheet_path))
            rows = []
            for row in sheet_root.findall(".//x:sheetData/x:row", ns):
                values = []
                for cell in row.findall("x:c", ns):
                    ref = cell.attrib.get("r", "")
                    match = re.match(r"([A-Z]+)", ref)
                    if match:
                        col_index = 0
                        for char in match.group(1):
                            col_index = col_index * 26 + ord(char) - 64
                        while len(values) < col_index - 1:
                            values.append("")
                    cell_type = cell.attrib.get("t")
                    if cell_type == "inlineStr":
                        node = cell.find("x:is", ns)
                        value = "".join(node.itertext()) if node is not None else ""
                    else:
                        node = cell.find("x:v", ns)
                        value = node.text if node is not None and node.text is not None else ""
                        if cell_type == "s" and value.isdigit():
                            value = shared_strings[int(value)] if int(value) < len(shared_strings) else ""
                    values.append(value)
                rows.append(values)
            worksheets.append((sheet_name, rows))
    return worksheets


def option_rows_to_excel_rows(rows: list[dict], identity_id: str, identity_label: str, export_type: str = "identity") -> list[list[str]]:
    columns = SINGLE_MATRIX_EXPORT_COLUMNS if export_type == "single_matrix" else IDENTITY_EXPORT_COLUMNS
    table = [[header for _key, header in columns]]
    for row in rows:
        enriched = dict(row)
        enriched["identity_id"] = identity_id
        enriched["identity_label"] = identity_label
        table.append([enriched.get(key, "") for key, _header in columns])
    return table


def excel_rows_to_options(rows: list[list[str]]) -> list[dict]:
    if not rows:
        return []
    header = [str(cell).strip() for cell in rows[0]]
    keys = [HEADER_TO_KEY.get(cell, "") for cell in header]
    options = []
    for row in rows[1:]:
        item = {}
        for index, key in enumerate(keys):
            if key:
                item[key] = row[index].strip() if index < len(row) else ""
        if item.get("label") or item.get("dimension_label") or item.get("value_key"):
            options.append(item)
    return options


def parse_ratio(value, default: float | None = None) -> float | None:
    text = str(value if value is not None else "").strip().replace("%", "")
    if not text:
        return default
    try:
        return float(text)
    except ValueError:
        return default


def format_ratio(value) -> str:
    ratio = parse_ratio(value, 0.0) or 0.0
    text = f"{ratio:.4f}".rstrip("0").rstrip(".")
    return text or "0"


def normalize_matrix_ratios(rows: list[dict]):
    enabled_rows = [row for row in rows if str(row.get("enabled", "TRUE")).upper() != "FALSE"]
    if not enabled_rows:
        return
    valid = []
    for row in enabled_rows:
        ratio = parse_ratio(row.get("ratio"))
        if ratio is None or ratio < 0:
            valid = []
            break
        valid.append(ratio)
    total = sum(valid) if valid else 0.0
    if valid and abs(total - 100.0) <= 0.01:
        for row, ratio in zip(enabled_rows, valid):
            row["ratio"] = format_ratio(ratio)
        return
    if total > 0:
        for row, ratio in zip(enabled_rows, valid):
            row["ratio"] = format_ratio(ratio * 100.0 / total)
        return
    equal = 100.0 / len(enabled_rows)
    for row in enabled_rows:
        row["ratio"] = format_ratio(equal)


def equalize_matrix_ratios(rows: list[dict]):
    enabled_rows = [row for row in rows if str(row.get("enabled", "TRUE")).upper() != "FALSE"]
    if not enabled_rows:
        return
    equal = 100.0 / len(enabled_rows)
    for row in enabled_rows:
        row["ratio"] = format_ratio(equal)


def randomize_matrix_ratios(rows: list[dict]):
    enabled_rows = [row for row in rows if str(row.get("enabled", "TRUE")).upper() != "FALSE"]
    if not enabled_rows:
        return
    points = [random.random() for _row in enabled_rows]
    total = sum(points) or 1.0
    for row, point in zip(enabled_rows, points):
        row["ratio"] = format_ratio(point * 100.0 / total)
    diff = 100.0 - sum(parse_ratio(row.get("ratio"), 0.0) or 0.0 for row in enabled_rows)
    enabled_rows[-1]["ratio"] = format_ratio((parse_ratio(enabled_rows[-1].get("ratio"), 0.0) or 0.0) + diff)


def normalize_option_ratios(rows: list[dict]):
    grouped = {}
    for row in rows:
        grouped.setdefault(row.get("dimension_id") or row.get("dimension_label", ""), []).append(row)
    for group in grouped.values():
        normalize_matrix_ratios(group)


def matrix_ratio_error(rows: list[dict]) -> str:
    enabled_rows = [row for row in rows if str(row.get("enabled", "TRUE")).upper() != "FALSE"]
    if not enabled_rows:
        return ""
    total = 0.0
    for row in enabled_rows:
        ratio = parse_ratio(row.get("ratio"))
        if ratio is None or ratio < 0:
            return "占比必须是大于等于 0 的 float 数值。"
        total += ratio
    if abs(total - 100.0) > 0.01:
        return f"当前矩阵占比合计为 {total:.4f}%，必须等于 100%。"
    return ""


def weighted_choice(rows: list[dict]) -> dict:
    if not rows:
        raise ValueError("rows is empty")
    weights = [max(parse_ratio(row.get("ratio"), 0.0) or 0.0, 0.0) for row in rows]
    total = sum(weights)
    if total <= 0:
        return random.choice(rows)
    return random.choices(rows, weights=weights, k=1)[0]


def templates_to_excel_rows(templates: list[dict]) -> list[list[str]]:
    rows = [["模板名称", "模板内容", "绑定角色ID", "适用风格大类", "适用具体画风", "矩阵名称"]]
    for template in templates:
        dimensions = template.get("dimensions") or [""]
        style_groups = "；".join(template.get("style_groups") or [])
        style_templates = "；".join(template.get("style_templates") or [])
        for dimension in dimensions:
            rows.append([
                template.get("name", ""),
                template.get("content", DEFAULT_TEMPLATE_CONTENT),
                template.get("bound_identity_id", ""),
                style_groups,
                style_templates,
                dimension,
            ])
    return rows


def excel_rows_to_templates(rows: list[list[str]]) -> list[dict]:
    if not rows:
        return []
    headers = [str(cell).strip() for cell in rows[0]]
    name_index = headers.index("模板名称") if "模板名称" in headers else 0
    content_index = headers.index("模板内容") if "模板内容" in headers else -1
    bound_index = headers.index("绑定角色ID") if "绑定角色ID" in headers else -1
    style_group_index = headers.index("适用风格大类") if "适用风格大类" in headers else -1
    style_template_index = headers.index("适用具体画风") if "适用具体画风" in headers else -1
    dimension_index = headers.index("矩阵名称") if "矩阵名称" in headers else 1
    grouped = {}
    contents = {}
    bound_identity_ids = {}
    style_groups = {}
    style_templates = {}
    order = []
    for row in rows[1:]:
        name = row[name_index].strip() if name_index < len(row) else ""
        dimension = row[dimension_index].strip() if dimension_index < len(row) else ""
        content = row[content_index].strip() if content_index >= 0 and content_index < len(row) else ""
        bound_identity_id = row[bound_index].strip() if bound_index >= 0 and bound_index < len(row) else ""
        style_group_text = row[style_group_index].strip() if style_group_index >= 0 and style_group_index < len(row) else ""
        style_template_text = row[style_template_index].strip() if style_template_index >= 0 and style_template_index < len(row) else ""
        if not name:
            continue
        if name not in grouped:
            grouped[name] = []
            contents[name] = content or DEFAULT_TEMPLATE_CONTENT
            bound_identity_ids[name] = bound_identity_id
            style_groups[name] = []
            style_templates[name] = []
            order.append(name)
        if content:
            contents[name] = content
        if bound_identity_id:
            bound_identity_ids[name] = bound_identity_id
        for item in re.split(r"[；;,\n、]+", style_group_text):
            item = item.strip()
            if item and item not in style_groups[name]:
                style_groups[name].append(item)
        for item in re.split(r"[；;,\n、]+", style_template_text):
            item = item.strip()
            if item and item not in style_templates[name]:
                style_templates[name].append(item)
        if dimension and dimension not in grouped[name]:
            grouped[name].append(dimension)
    templates = []
    for index, name in enumerate(order, start=1):
        templates.append(
            {
                "id": f"import_template_{index}_{datetime.now():%H%M%S}",
                "name": name,
                "content": contents.get(name, DEFAULT_TEMPLATE_CONTENT),
                "bound_identity_id": bound_identity_ids.get(name, ""),
                "dimensions": grouped[name],
                "style_groups": style_groups.get(name, []),
                "style_templates": style_templates.get(name, []),
            }
        )
    return templates


def fixed_templates_to_excel_rows(templates: list[dict]) -> list[list[str]]:
    rows = [["模板名称", "模板内容"]]
    for template in templates:
        rows.append([
            str(template.get("name", "")),
            str(template.get("content", "")),
        ])
    return rows


def excel_rows_to_fixed_templates(rows: list[list[str]]) -> list[dict]:
    if not rows:
        return []
    headers = [str(cell).strip() for cell in rows[0]]
    name_index = headers.index("模板名称") if "模板名称" in headers else 0
    content_index = headers.index("模板内容") if "模板内容" in headers else (1 if len(headers) > 1 else -1)
    templates = []
    by_name = {}
    for row in rows[1:]:
        name = row[name_index].strip() if name_index < len(row) else ""
        content = row[content_index].strip() if content_index >= 0 and content_index < len(row) else ""
        if not name:
            continue
        if name in by_name:
            by_name[name]["content"] = content
            continue
        template = {"name": name, "content": content}
        templates.append(template)
        by_name[name] = template
    return templates


def load_js_payload(path: Path, variable_name: str) -> dict:
    text = path.read_text(encoding="utf-8-sig")
    match = re.search(rf"window\.{re.escape(variable_name)}\s*=\s*(.*);\s*$", text, re.S)
    if not match:
        raise ValueError(f"无法从 {path} 读取 {variable_name}")
    return json.loads(match.group(1))


def load_base_options() -> list[dict]:
    payload = load_js_payload(DOCUMENT_MATRIX_PATH, "PIC_FACTORY_DOCUMENT_MATRICES")
    sheets = {sheet["key"]: sheet for sheet in payload["sheets"]}
    return sheets["matrix_options_full"]["rows"]


def is_identity_option(row: dict, identity_id: str) -> bool:
    if row.get("module") != "character":
        return False
    scope = row.get("role_scope", "")
    return scope in {identity_id, "all", "custom", ""}


def base_options_for_identity(base_options: list[dict], identity_id: str) -> list[dict]:
    return [copy.deepcopy(row) for row in base_options if is_identity_option(row, identity_id)]


def matrix_db_connect() -> sqlite3.Connection:
    if getattr(sys, "frozen", False) and not MATRIX_DB_PATH.exists() and PACKAGED_MATRIX_DB_PATH.exists():
        try:
            shutil.copy2(PACKAGED_MATRIX_DB_PATH, MATRIX_DB_PATH)
        except OSError:
            pass
    # Concurrent batch workers write this database, so wait for a busy lock
    # instead of raising OperationalError immediately.
    conn = sqlite3.connect(MATRIX_DB_PATH, timeout=30.0)
    conn.row_factory = sqlite3.Row
    return conn


@contextlib.contextmanager
def closing_db_connection():
    """Yield a connection and always close it.

    ``with sqlite3.Connection`` only commits or rolls back; it never releases the
    file handle. Long batches open a connection per call, so leaving them to the
    garbage collector accumulated handles and grew the WAL file.
    """
    conn = matrix_db_connect()
    try:
        with conn:
            yield conn
    finally:
        conn.close()


def checkpoint_matrix_db(mode: str = "PASSIVE") -> None:
    """Fold the write-ahead log back into the database file.

    WAL mode only truncates the sidecar file on a checkpoint, and the app never
    requested one, so it grew past 300 MB. TRUNCATE also returns the space to
    the filesystem; PASSIVE never blocks a concurrent reader.
    """
    try:
        with closing_db_connection() as conn:
            conn.execute(f"PRAGMA wal_checkpoint({mode})")
    except sqlite3.Error:
        # A busy checkpoint is harmless: the next save retries it.
        pass


def ensure_matrix_db() -> None:
    global _MATRIX_DB_READY
    if _MATRIX_DB_READY:
        return
    with _MATRIX_DB_READY_LOCK:
        if _MATRIX_DB_READY:
            return
        with closing_db_connection() as conn:
            conn.executescript(
                """
                PRAGMA journal_mode=WAL;
                PRAGMA synchronous=NORMAL;
                CREATE TABLE IF NOT EXISTS metadata (
                    key TEXT PRIMARY KEY,
                    value TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS app_collections (
                    namespace TEXT NOT NULL,
                    item_key TEXT NOT NULL,
                    payload TEXT NOT NULL,
                    sort_order INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    PRIMARY KEY(namespace, item_key)
                );
                CREATE INDEX IF NOT EXISTS idx_app_collections_namespace
                    ON app_collections(namespace, sort_order, item_key);
                CREATE TABLE IF NOT EXISTS matrix_dimensions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    dimension_key TEXT NOT NULL,
                    dimension_label TEXT NOT NULL,
                    module TEXT NOT NULL,
                    category TEXT DEFAULT '',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(dimension_key, module)
                );
                CREATE TABLE IF NOT EXISTS matrix_items (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    dimension_id INTEGER NOT NULL,
                    item_key TEXT NOT NULL,
                    label TEXT NOT NULL,
                    value_key TEXT DEFAULT '',
                    source_line TEXT DEFAULT '',
                    notes TEXT DEFAULT '',
                    sub_category TEXT DEFAULT '',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(dimension_id, item_key),
                    FOREIGN KEY(dimension_id) REFERENCES matrix_dimensions(id)
                );
                CREATE TABLE IF NOT EXISTS identity_matrix_bindings (
                    role_id TEXT NOT NULL,
                    identity_id TEXT NOT NULL,
                    dimension_id INTEGER NOT NULL,
                    enabled INTEGER DEFAULT 1,
                    sort_order INTEGER DEFAULT 0,
                    PRIMARY KEY(role_id, identity_id, dimension_id),
                    FOREIGN KEY(dimension_id) REFERENCES matrix_dimensions(id)
                );
                CREATE TABLE IF NOT EXISTS identity_matrix_item_bindings (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    role_id TEXT NOT NULL,
                    identity_id TEXT NOT NULL,
                    dimension_id INTEGER NOT NULL,
                    item_id INTEGER NOT NULL,
                    option_id TEXT DEFAULT '',
                    ratio TEXT DEFAULT '',
                    enabled TEXT DEFAULT 'TRUE',
                    role_scope TEXT DEFAULT '',
                    category TEXT DEFAULT '',
                    sub_category TEXT DEFAULT '',
                    notes TEXT DEFAULT '',
                    value_key TEXT DEFAULT '',
                    source_line TEXT DEFAULT '',
                    sort_order INTEGER DEFAULT 0,
                    FOREIGN KEY(dimension_id) REFERENCES matrix_dimensions(id),
                    FOREIGN KEY(item_id) REFERENCES matrix_items(id)
                );
                CREATE INDEX IF NOT EXISTS idx_identity_matrix_bindings_scope
                    ON identity_matrix_bindings(role_id, identity_id);
                CREATE INDEX IF NOT EXISTS idx_identity_matrix_item_bindings_scope
                    ON identity_matrix_item_bindings(role_id, identity_id, dimension_id);
                CREATE INDEX IF NOT EXISTS idx_matrix_items_dimension
                    ON matrix_items(dimension_id);
                CREATE TABLE IF NOT EXISTS style_groups (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    sort_order INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
                CREATE TABLE IF NOT EXISTS style_templates (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    group_id INTEGER NOT NULL,
                    name TEXT NOT NULL,
                    sort_order INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(group_id, name),
                    FOREIGN KEY(group_id) REFERENCES style_groups(id)
                );
                CREATE TABLE IF NOT EXISTS style_matrices (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    template_id INTEGER NOT NULL,
                    name TEXT NOT NULL,
                    sort_order INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(template_id, name),
                    FOREIGN KEY(template_id) REFERENCES style_templates(id)
                );
                CREATE TABLE IF NOT EXISTS style_matrix_items (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    matrix_id INTEGER NOT NULL,
                    name TEXT NOT NULL,
                    note TEXT DEFAULT '',
                    used INTEGER DEFAULT 1,
                    sort_order INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY(matrix_id) REFERENCES style_matrices(id)
                );
                CREATE TABLE IF NOT EXISTS persona_profiles (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    serial_no TEXT DEFAULT '',
                    detail TEXT DEFAULT '',
                    note TEXT DEFAULT '',
                    note1 TEXT DEFAULT '',
                    note2 TEXT DEFAULT '',
                    sort_order INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
                CREATE INDEX IF NOT EXISTS idx_style_templates_group
                    ON style_templates(group_id, sort_order);
                CREATE INDEX IF NOT EXISTS idx_style_matrices_template
                    ON style_matrices(template_id, sort_order);
                CREATE INDEX IF NOT EXISTS idx_style_matrix_items_matrix
                    ON style_matrix_items(matrix_id, sort_order);
                CREATE INDEX IF NOT EXISTS idx_persona_profiles_sort
                    ON persona_profiles(sort_order, id);
                """
            )
        _MATRIX_DB_READY = True


def load_db_collection(namespace: str) -> list[dict]:
    ensure_matrix_db()
    with closing_db_connection() as conn:
        rows = conn.execute(
            "SELECT item_key, payload FROM app_collections WHERE namespace = ? ORDER BY sort_order, item_key",
            (namespace,),
        ).fetchall()
    result = []
    for row in rows:
        try:
            value = json.loads(row["payload"])
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if isinstance(value, dict):
            result.append(value)
    # 画风管理按记录更新时间倒序展示，确保新增或最近编辑的画风始终在最前。
    # 其他集合继续沿用各自的显式 sort_order。
    if namespace == "fixed_style_templates":
        result.sort(key=lambda value: str(value.get("updated_at", "") or "").strip(), reverse=True)
    _DB_COLLECTION_DIGESTS[namespace] = hashlib.sha1(json.dumps(result, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    return result


def save_db_collection(namespace: str, values: list[dict]) -> None:
    ensure_matrix_db()
    normalized = [value for value in values if isinstance(value, dict)]
    if namespace == "fixed_style_templates":
        normalized.sort(key=lambda value: str(value.get("updated_at", "") or "").strip(), reverse=True)
        if isinstance(values, list):
            values[:] = normalized
    digest = hashlib.sha1(json.dumps(normalized, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    if _DB_COLLECTION_DIGESTS.get(namespace) == digest:
        return
    with closing_db_connection() as conn:
        conn.execute("DELETE FROM app_collections WHERE namespace = ?", (namespace,))
        conn.executemany(
            """
            INSERT INTO app_collections(namespace, item_key, payload, sort_order, updated_at)
            VALUES(?, ?, ?, ?, CURRENT_TIMESTAMP)
            ON CONFLICT(namespace, item_key) DO UPDATE SET
                payload = excluded.payload,
                sort_order = excluded.sort_order,
                updated_at = CURRENT_TIMESTAMP
            """,
            [
                (
                    namespace,
                    str(value.get("uuid") or value.get("id") or value.get("name") or index),
                    json.dumps(value, ensure_ascii=False, separators=(",", ":")),
                    index,
                )
                for index, value in enumerate(normalized)
            ],
        )
    _DB_COLLECTION_DIGESTS[namespace] = digest


def db_collection_item_key(value: dict, index: int = 0) -> str:
    """Mirror the item_key that save_db_collection derives for one record."""
    return str(value.get("uuid") or value.get("id") or value.get("name") or index)


def upsert_db_collection_item(namespace: str, value: dict) -> None:
    """Persist a single record without rewriting the whole namespace.

    ``generated_works`` carries the full scene payload of every finished title.
    Rewriting that namespace costs seconds once it grows large, so a batch that
    finishes one title at a time only needs this one row written.
    """
    ensure_matrix_db()
    if not isinstance(value, dict):
        return
    # The in-memory digest cache no longer describes the stored namespace.
    _DB_COLLECTION_DIGESTS.pop(namespace, None)
    item_key = db_collection_item_key(value)
    with closing_db_connection() as conn:
        conn.execute(
            """
            INSERT INTO app_collections(namespace, item_key, payload, sort_order, updated_at)
            VALUES(
                ?, ?, ?,
                COALESCE((SELECT sort_order FROM app_collections WHERE namespace = ? AND item_key = ?), 0),
                CURRENT_TIMESTAMP
            )
            ON CONFLICT(namespace, item_key) DO UPDATE SET
                payload = excluded.payload,
                updated_at = CURRENT_TIMESTAMP
            """,
            (namespace, item_key, json.dumps(value, ensure_ascii=False, separators=(",", ":")), namespace, item_key),
        )


def upsert_db_collection_items(namespace: str, values: list[dict]) -> None:
    """Persist a small set of changed records in one transaction."""
    ensure_matrix_db()
    rows = [value for value in values if isinstance(value, dict)]
    if not rows:
        return
    _DB_COLLECTION_DIGESTS.pop(namespace, None)
    with closing_db_connection() as conn:
        for value in rows:
            item_key = db_collection_item_key(value)
            conn.execute(
                """
                INSERT INTO app_collections(namespace, item_key, payload, sort_order, updated_at)
                VALUES(
                    ?, ?, ?,
                    COALESCE((SELECT sort_order FROM app_collections WHERE namespace = ? AND item_key = ?), 0),
                    CURRENT_TIMESTAMP
                )
                ON CONFLICT(namespace, item_key) DO UPDATE SET
                    payload = excluded.payload,
                    updated_at = CURRENT_TIMESTAMP
                """,
                (namespace, item_key, json.dumps(value, ensure_ascii=False, separators=(",", ":")), namespace, item_key),
            )


def remove_db_collection(namespace: str) -> None:
    """Remove an obsolete collection while keeping the SQLite schema intact."""
    ensure_matrix_db()
    with closing_db_connection() as conn:
        conn.execute("DELETE FROM app_collections WHERE namespace = ?", (namespace,))
    _DB_COLLECTION_DIGESTS.pop(namespace, None)


def load_db_collection_map(namespace: str) -> dict:
    ensure_matrix_db()
    with closing_db_connection() as conn:
        rows = conn.execute(
            "SELECT item_key, payload FROM app_collections WHERE namespace = ? ORDER BY sort_order, item_key",
            (namespace,),
        ).fetchall()
    result = {}
    for row in rows:
        try:
            value = json.loads(row["payload"])
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        result[str(row["item_key"])] = value
    _DB_COLLECTION_DIGESTS[namespace] = hashlib.sha1(json.dumps(result, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    return result


def save_db_collection_map(namespace: str, values: dict) -> None:
    ensure_matrix_db()
    if not isinstance(values, dict):
        return
    digest = hashlib.sha1(json.dumps(values, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    if _DB_COLLECTION_DIGESTS.get(namespace) == digest:
        return
    with closing_db_connection() as conn:
        conn.execute("DELETE FROM app_collections WHERE namespace = ?", (namespace,))
        conn.executemany(
            """
            INSERT INTO app_collections(namespace, item_key, payload, sort_order, updated_at)
            VALUES(?, ?, ?, ?, CURRENT_TIMESTAMP)
            """,
            [
                (namespace, str(key), json.dumps(value, ensure_ascii=False, separators=(",", ":")), index)
                for index, (key, value) in enumerate(values.items())
            ],
        )
    _DB_COLLECTION_DIGESTS[namespace] = digest


DB_COLLECTION_LIST_SPECS = (
    ("fixed_style_templates", "fixed_style_templates"),
    ("fixed_identity_templates", "fixed_identity_templates"),
    ("build_templates", "build_templates"),
    ("style_build_templates", "style_build_templates"),
    ("roles", "roles"),
    ("character_identities", "character_identities"),
    ("wechat_accounts", "wechat_accounts"),
    ("reference_images", "reference_images"),
    ("title_library", "title_library"),
    ("users", "users"),
    ("article_prompts", "article_prompts"),
    ("comment_prompts", "comment_prompts"),
    ("storyboard_prompt_rules", "storyboard_prompt_rules"),
    ("generated_works", "generated_works"),
)

DB_COLLECTION_NESTED_SPECS = (
    ("batch_writing_config", "prompt_templates", "batch_writing_prompt_templates"),
    ("writing_config", "prompt_templates", "writing_prompt_templates"),
    ("image_batch_config", "prompt_templates", "image_batch_prompt_templates"),
)

DB_SETTINGS_KEYS = (
    "active_role_id",
    "identity_default_build_templates",
    "storyboard_config",
    "writing_config",
    "batch_writing_config",
    "image_batch_config",
    "illustration_batch_config",
    "style_management_config",
    "account_generation_config",
)

# These keys belonged to the removed role/style injection controls.  Keep the
# migration one-way: old state files may still contain them, but new runtime
# configs only persist the selected style name.
LEGACY_STYLE_CONFIG_KEYS = {
    "identity_mode",
    "style_mode",
    "fixed_identity_template",
    "fixed_style_template",
    "style_template",
    "style_groups",
    "style_templates",
}


def sanitize_production_style_configs(state: dict) -> None:
    """Remove legacy injection settings while retaining the style name."""
    for config_key in (
        "storyboard_config",
        "writing_config",
        "batch_writing_config",
        "image_batch_config",
        "illustration_batch_config",
    ):
        config = state.get(config_key)
        if not isinstance(config, dict):
            continue
        for legacy_key in LEGACY_STYLE_CONFIG_KEYS:
            config.pop(legacy_key, None)


def hydrate_db_settings(state: dict) -> None:
    stored = load_db_collection_map("app_settings")
    source = {key: state[key] for key in DB_SETTINGS_KEYS if key in state}
    if not stored and source:
        save_db_collection_map("app_settings", source)
        stored = source
    for key, value in stored.items():
        if key in DB_SETTINGS_KEYS:
            if key in {"storyboard_config", "writing_config", "batch_writing_config", "image_batch_config", "illustration_batch_config"} and isinstance(value, dict):
                current = state.get(key, {})
                merged = dict(current) if isinstance(current, dict) else {}
                merged.update(value)
                state[key] = merged
            else:
                state[key] = value


def persist_db_settings(state: dict) -> None:
    values = {}
    for key in DB_SETTINGS_KEYS:
        if key not in state:
            continue
        value = copy.deepcopy(state[key])
        if key in {"storyboard_config", "writing_config", "batch_writing_config", "image_batch_config", "illustration_batch_config"} and isinstance(value, dict):
            value.pop("prompt_templates", None)
        values[key] = value
    save_db_collection_map("app_settings", values)


def hydrate_db_role_global_options(state: dict) -> None:
    stored = load_db_collection_map("role_global_options")
    source = {}
    for role in state.get("roles", []):
        if isinstance(role, dict) and role.get("id"):
            source[str(role["id"])] = role.get("global_options", [])
    if not stored and source:
        save_db_collection_map("role_global_options", source)
        stored = source
    for role in state.get("roles", []):
        if not isinstance(role, dict):
            continue
        role_id = str(role.get("id", ""))
        if role_id in stored and isinstance(stored[role_id], list):
            role["global_options"] = stored[role_id]


def persist_db_role_global_options(state: dict) -> None:
    values = {}
    for role in state.get("roles", []):
        if isinstance(role, dict) and role.get("id"):
            values[str(role["id"])] = role.get("global_options", [])
    save_db_collection_map("role_global_options", values)


def hydrate_db_collections(state: dict) -> None:
    """Use SQLite as the source of truth for growing template/role collections."""
    ensure_matrix_db()
    for state_key, namespace in DB_COLLECTION_LIST_SPECS:
        source = state.get(state_key)
        stored = load_db_collection(namespace)
        if stored:
            state[state_key] = stored
        elif isinstance(source, list) and source:
            save_db_collection(namespace, source)
    for config_key, item_key, namespace in DB_COLLECTION_NESTED_SPECS:
        config = state.setdefault(config_key, {})
        source = config.get(item_key)
        stored = load_db_collection(namespace)
        if stored:
            config[item_key] = stored
        elif isinstance(source, list) and source:
            save_db_collection(namespace, source)
    hydrate_db_role_global_options(state)


def persist_db_collections(state: dict) -> None:
    ensure_matrix_db()
    for state_key, namespace in DB_COLLECTION_LIST_SPECS:
        values = state.get(state_key)
        if isinstance(values, list):
            if state_key == "roles":
                values = []
                for role in state.get("roles", []):
                    if not isinstance(role, dict):
                        continue
                    compact_role = {key: copy.deepcopy(value) for key, value in role.items() if key not in {"identity_options", "global_options"}}
                    compact_role["identity_options"] = {}
                    values.append(compact_role)
            save_db_collection(namespace, values)
    persist_db_role_global_options(state)
    for config_key, item_key, namespace in DB_COLLECTION_NESTED_SPECS:
        config = state.get(config_key, {})
        values = config.get(item_key) if isinstance(config, dict) else None
        if isinstance(values, list):
            save_db_collection(namespace, values)


def db_metadata_value(key: str) -> str:
    ensure_matrix_db()
    with closing_db_connection() as conn:
        row = conn.execute("SELECT value FROM metadata WHERE key = ?", (key,)).fetchone()
        return row["value"] if row else ""


def set_db_metadata_value(key: str, value: str) -> None:
    ensure_matrix_db()
    with closing_db_connection() as conn:
        conn.execute(
            "INSERT INTO metadata(key, value) VALUES(?, ?) "
            "ON CONFLICT(key) DO UPDATE SET value = excluded.value",
            (key, value),
        )


PERSONA_PROFILE_COLUMNS = ["序号", "人设详情", "备注", "备注1", "备注2"]


def load_persona_profiles() -> list[dict]:
    ensure_matrix_db()
    with closing_db_connection() as conn:
        rows = conn.execute(
            """
            SELECT id, serial_no, detail, note, note1, note2, sort_order
            FROM persona_profiles
            ORDER BY sort_order, id
            """
        ).fetchall()
    return [
        {
            "id": int(row["id"]),
            "serial_no": row["serial_no"] or "",
            "detail": row["detail"] or "",
            "note": row["note"] or "",
            "note1": row["note1"] or "",
            "note2": row["note2"] or "",
            "sort_order": int(row["sort_order"] or 0),
        }
        for row in rows
    ]


def save_persona_profile(profile: dict) -> int:
    ensure_matrix_db()
    profile_id = int(profile.get("id") or 0)
    serial_no = str(profile.get("serial_no", "")).strip()
    detail = str(profile.get("detail", "")).strip()
    note = str(profile.get("note", "")).strip()
    note1 = str(profile.get("note1", "")).strip()
    note2 = str(profile.get("note2", "")).strip()
    sort_order = int(profile.get("sort_order") or 0)
    with closing_db_connection() as conn:
        if profile_id:
            conn.execute(
                """
                UPDATE persona_profiles
                SET serial_no = ?, detail = ?, note = ?, note1 = ?, note2 = ?,
                    sort_order = ?, updated_at = CURRENT_TIMESTAMP
                WHERE id = ?
                """,
                (serial_no, detail, note, note1, note2, sort_order, profile_id),
            )
            return profile_id
        cur = conn.execute(
            """
            INSERT INTO persona_profiles(serial_no, detail, note, note1, note2, sort_order, updated_at)
            VALUES(?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
            """,
            (serial_no, detail, note, note1, note2, sort_order),
        )
        return int(cur.lastrowid)


def delete_persona_profile(profile_id: int) -> None:
    ensure_matrix_db()
    with closing_db_connection() as conn:
        conn.execute("DELETE FROM persona_profiles WHERE id = ?", (int(profile_id),))


def persona_profiles_to_excel_rows(profiles: list[dict]) -> list[list[str]]:
    rows = [PERSONA_PROFILE_COLUMNS[:]]
    for profile in profiles:
        rows.append([
            profile.get("serial_no", ""),
            profile.get("detail", ""),
            profile.get("note", ""),
            profile.get("note1", ""),
            profile.get("note2", ""),
        ])
    return rows


def excel_rows_to_persona_profiles(rows: list[list[str]]) -> list[dict]:
    if not rows:
        return []
    headers = [str(cell).strip() for cell in rows[0]]
    index_map = {name: headers.index(name) for name in PERSONA_PROFILE_COLUMNS if name in headers}
    profiles = []
    for row_index, row in enumerate(rows[1:], start=1):
        def cell(name: str) -> str:
            index = index_map.get(name)
            if index is None or index >= len(row):
                return ""
            return str(row[index]).strip()

        profile = {
            "serial_no": cell("序号") or str(row_index),
            "detail": cell("人设详情"),
            "note": cell("备注"),
            "note1": cell("备注1"),
            "note2": cell("备注2"),
            "sort_order": row_index - 1,
        }
        if any(profile.get(key, "") for key in ("serial_no", "detail", "note", "note1", "note2")):
            profiles.append(profile)
    return profiles


def matrix_item_key(row: dict) -> str:
    payload = {
        "label": row.get("label", ""),
        "value_key": row.get("value_key", ""),
        "source_line": row.get("source_line", ""),
        "notes": row.get("notes", ""),
        "sub_category": row.get("sub_category", ""),
    }
    raw = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha1(raw.encode("utf-8")).hexdigest()


def upsert_matrix_dimension(conn: sqlite3.Connection, row: dict) -> int:
    dimension_key = row.get("dimension_id") or row.get("dimension_label", "")
    dimension_label = row.get("dimension_label", "") or dimension_key
    module = row.get("module", "") or "character"
    category = row.get("category", "")
    conn.execute(
        """
        INSERT INTO matrix_dimensions(dimension_key, dimension_label, module, category, updated_at)
        VALUES(?, ?, ?, ?, CURRENT_TIMESTAMP)
        ON CONFLICT(dimension_key, module) DO UPDATE SET
            dimension_label = excluded.dimension_label,
            category = excluded.category,
            updated_at = CURRENT_TIMESTAMP
        """,
        (dimension_key, dimension_label, module, category),
    )
    found = conn.execute(
        "SELECT id FROM matrix_dimensions WHERE dimension_key = ? AND module = ?",
        (dimension_key, module),
    ).fetchone()
    return int(found["id"])


def upsert_matrix_item(conn: sqlite3.Connection, dimension_id: int, row: dict) -> int:
    item_key = matrix_item_key(row)
    conn.execute(
        """
        INSERT INTO matrix_items(dimension_id, item_key, label, value_key, source_line, notes, sub_category, updated_at)
        VALUES(?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
        ON CONFLICT(dimension_id, item_key) DO UPDATE SET
            label = excluded.label,
            value_key = excluded.value_key,
            source_line = excluded.source_line,
            notes = excluded.notes,
            sub_category = excluded.sub_category,
            updated_at = CURRENT_TIMESTAMP
        """,
        (
            dimension_id,
            item_key,
            row.get("label", ""),
            row.get("value_key", ""),
            row.get("source_line", ""),
            row.get("notes", ""),
            row.get("sub_category", ""),
        ),
    )
    found = conn.execute(
        "SELECT id FROM matrix_items WHERE dimension_id = ? AND item_key = ?",
        (dimension_id, item_key),
    ).fetchone()
    return int(found["id"])


_IDENTITY_OPTIONS_WRITE_DIGESTS = {}


def save_identity_options_to_db(role_id: str, identity_id: str, rows: list[dict]) -> None:
    ensure_matrix_db()
    rows = [copy.deepcopy(row) for row in rows if isinstance(row, dict)]
    normalize_option_ratios(rows)
    # Deleting and re-inserting unchanged rows is pure overhead: a full flush
    # rewrites every loaded role/identity pair on each save. Skip the write when
    # this exact content is already stored, on the first attempt and after a
    # reload. A database error clears the mark so the next save retries.
    cache_key = (str(role_id), str(identity_id))
    digest = hashlib.sha1(
        json.dumps(rows, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    ).hexdigest()
    if _IDENTITY_OPTIONS_WRITE_DIGESTS.get(cache_key) == digest:
        return
    try:
        with closing_db_connection() as conn:
            conn.execute("BEGIN")
            conn.execute(
                "DELETE FROM identity_matrix_item_bindings WHERE role_id = ? AND identity_id = ?",
                (role_id, identity_id),
            )
            conn.execute(
                "DELETE FROM identity_matrix_bindings WHERE role_id = ? AND identity_id = ?",
                (role_id, identity_id),
            )
            dimension_orders = {}
            for index, row in enumerate(rows):
                if not row.get("dimension_label") or not row.get("label"):
                    continue
                dimension_id = upsert_matrix_dimension(conn, row)
                if dimension_id not in dimension_orders:
                    dimension_orders[dimension_id] = len(dimension_orders)
                    conn.execute(
                        """
                        INSERT INTO identity_matrix_bindings(role_id, identity_id, dimension_id, enabled, sort_order)
                        VALUES(?, ?, ?, 1, ?)
                        ON CONFLICT(role_id, identity_id, dimension_id) DO UPDATE SET
                            enabled = excluded.enabled,
                            sort_order = excluded.sort_order
                        """,
                        (role_id, identity_id, dimension_id, dimension_orders[dimension_id]),
                    )
                item_id = upsert_matrix_item(conn, dimension_id, row)
                conn.execute(
                    """
                    INSERT INTO identity_matrix_item_bindings(
                        role_id, identity_id, dimension_id, item_id, option_id, ratio, enabled,
                        role_scope, category, sub_category, notes, value_key, source_line, sort_order
                    )
                    VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                (
                    role_id,
                    identity_id,
                    dimension_id,
                    item_id,
                    row.get("option_id", ""),
                    str(row.get("ratio", "")),
                    row.get("enabled", "TRUE"),
                    row.get("role_scope", identity_id),
                    row.get("category", ""),
                    row.get("sub_category", ""),
                    row.get("notes", ""),
                    row.get("value_key", ""),
                    row.get("source_line", ""),
                    index,
                ),
                )
            conn.commit()
    except Exception:
        _IDENTITY_OPTIONS_WRITE_DIGESTS.pop(cache_key, None)
        raise
    _IDENTITY_OPTIONS_WRITE_DIGESTS[cache_key] = digest


def identity_options_exist_in_db(role_id: str, identity_id: str) -> bool:
    ensure_matrix_db()
    with closing_db_connection() as conn:
        row = conn.execute(
            "SELECT 1 FROM identity_matrix_bindings WHERE role_id = ? AND identity_id = ? LIMIT 1",
            (role_id, identity_id),
        ).fetchone()
        return row is not None


def load_identity_options_from_db(role_id: str, identity_id: str) -> list[dict]:
    ensure_matrix_db()
    with closing_db_connection() as conn:
        rows = conn.execute(
            """
            SELECT
                d.dimension_key,
                d.dimension_label,
                d.module,
                b.option_id,
                b.ratio,
                b.enabled,
                b.role_scope,
                COALESCE(NULLIF(b.category, ''), d.category) AS category,
                COALESCE(NULLIF(b.sub_category, ''), i.sub_category) AS sub_category,
                i.label,
                COALESCE(NULLIF(b.value_key, ''), i.value_key) AS value_key,
                COALESCE(NULLIF(b.source_line, ''), i.source_line) AS source_line,
                COALESCE(NULLIF(b.notes, ''), i.notes) AS notes
            FROM identity_matrix_item_bindings b
            JOIN matrix_dimensions d ON d.id = b.dimension_id
            JOIN matrix_items i ON i.id = b.item_id
            JOIN identity_matrix_bindings mb
                ON mb.role_id = b.role_id
                AND mb.identity_id = b.identity_id
                AND mb.dimension_id = b.dimension_id
            WHERE b.role_id = ? AND b.identity_id = ? AND mb.enabled = 1
            ORDER BY mb.sort_order, b.sort_order, b.id
            """,
            (role_id, identity_id),
        ).fetchall()
    result = []
    for row in rows:
        result.append(
            {
                "option_id": row["option_id"],
                "dimension_id": row["dimension_key"],
                "dimension_label": row["dimension_label"],
                "module": row["module"],
                "role_scope": row["role_scope"] or identity_id,
                "category": row["category"] or "",
                "sub_category": row["sub_category"] or "",
                "label": row["label"] or "",
                "value_key": row["value_key"] or "",
                "source_line": row["source_line"] or "",
                "enabled": row["enabled"] or "TRUE",
                "notes": row["notes"] or "",
                "ratio": row["ratio"] or "",
            }
        )
    normalize_option_ratios(result)
    return result


def copy_role_options_in_db(source_role_id: str, target_role_id: str) -> None:
    ensure_matrix_db()
    with closing_db_connection() as conn:
        conn.execute("BEGIN")
        conn.execute("DELETE FROM identity_matrix_item_bindings WHERE role_id = ?", (target_role_id,))
        conn.execute("DELETE FROM identity_matrix_bindings WHERE role_id = ?", (target_role_id,))
        conn.execute(
            """
            INSERT INTO identity_matrix_bindings(role_id, identity_id, dimension_id, enabled, sort_order)
            SELECT ?, identity_id, dimension_id, enabled, sort_order
            FROM identity_matrix_bindings
            WHERE role_id = ?
            """,
            (target_role_id, source_role_id),
        )
        conn.execute(
            """
            INSERT INTO identity_matrix_item_bindings(
                role_id, identity_id, dimension_id, item_id, option_id, ratio, enabled,
                role_scope, category, sub_category, notes, value_key, source_line, sort_order
            )
            SELECT
                ?, identity_id, dimension_id, item_id, option_id, ratio, enabled,
                role_scope, category, sub_category, notes, value_key, source_line, sort_order
            FROM identity_matrix_item_bindings
            WHERE role_id = ?
            """,
            (target_role_id, source_role_id),
        )
        conn.commit()
    # This function bypasses save_identity_options_to_db, so any digest cached
    # for the target role no longer describes what is stored.
    for cache_key in [key for key in _IDENTITY_OPTIONS_WRITE_DIGESTS if key[0] == str(target_role_id)]:
        _IDENTITY_OPTIONS_WRITE_DIGESTS.pop(cache_key, None)


def style_item_used_bool(value) -> bool:
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() not in {"false", "0", "no", "n", "否", "禁用", "禁止"}


def save_style_maintenance_to_db(config: dict) -> None:
    ensure_matrix_db()
    groups = config.get("groups", []) if isinstance(config, dict) else []
    with closing_db_connection() as conn:
        conn.execute("BEGIN")
        conn.execute("DELETE FROM style_matrix_items")
        conn.execute("DELETE FROM style_matrices")
        conn.execute("DELETE FROM style_templates")
        conn.execute("DELETE FROM style_groups")
        for group_index, group in enumerate(groups):
            group_name = str(group.get("name", "")).strip()
            if not group_name:
                continue
            cur = conn.execute(
                "INSERT INTO style_groups(name, sort_order, updated_at) VALUES(?, ?, CURRENT_TIMESTAMP)",
                (group_name, group_index),
            )
            group_id = cur.lastrowid
            for template_index, template in enumerate(group.get("templates", [])):
                template_name = str(template.get("name", "")).strip()
                if not template_name:
                    continue
                cur = conn.execute(
                    """
                    INSERT INTO style_templates(group_id, name, sort_order, updated_at)
                    VALUES(?, ?, ?, CURRENT_TIMESTAMP)
                    """,
                    (group_id, template_name, template_index),
                )
                template_id = cur.lastrowid
                for matrix_index, matrix in enumerate(template.get("matrices", [])):
                    matrix_name = str(matrix.get("name", "")).strip()
                    if not matrix_name:
                        continue
                    cur = conn.execute(
                        """
                        INSERT INTO style_matrices(template_id, name, sort_order, updated_at)
                        VALUES(?, ?, ?, CURRENT_TIMESTAMP)
                        """,
                        (template_id, matrix_name, matrix_index),
                    )
                    matrix_id = cur.lastrowid
                    for item_index, item in enumerate(matrix.get("items", [])):
                        item_name = str(item.get("name", "")).strip()
                        if not item_name:
                            continue
                        used = 1 if style_item_used_bool(item.get("used", True)) else 0
                        conn.execute(
                            """
                            INSERT INTO style_matrix_items(matrix_id, name, note, used, sort_order, updated_at)
                            VALUES(?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                            """,
                            (matrix_id, item_name, item.get("note", ""), used, item_index),
                        )
        conn.execute(
            "INSERT INTO metadata(key, value) VALUES('style_maintenance_migrated_at', ?) "
            "ON CONFLICT(key) DO UPDATE SET value = excluded.value",
            (datetime.now().isoformat(timespec="seconds"),),
        )
        conn.commit()


def style_maintenance_exists_in_db() -> bool:
    ensure_matrix_db()
    with closing_db_connection() as conn:
        row = conn.execute("SELECT 1 FROM style_groups LIMIT 1").fetchone()
        return row is not None


def load_style_maintenance_from_db() -> dict:
    ensure_matrix_db()
    with closing_db_connection() as conn:
        group_rows = conn.execute(
            "SELECT id, name FROM style_groups ORDER BY sort_order, id"
        ).fetchall()
        config = {"groups": []}
        for group_row in group_rows:
            group = {"name": group_row["name"], "templates": []}
            template_rows = conn.execute(
                "SELECT id, name FROM style_templates WHERE group_id = ? ORDER BY sort_order, id",
                (group_row["id"],),
            ).fetchall()
            for template_row in template_rows:
                template = {"name": template_row["name"], "matrices": []}
                matrix_rows = conn.execute(
                    "SELECT id, name FROM style_matrices WHERE template_id = ? ORDER BY sort_order, id",
                    (template_row["id"],),
                ).fetchall()
                for matrix_row in matrix_rows:
                    matrix = {"name": matrix_row["name"], "items": []}
                    item_rows = conn.execute(
                        "SELECT name, note, used FROM style_matrix_items WHERE matrix_id = ? ORDER BY sort_order, id",
                        (matrix_row["id"],),
                    ).fetchall()
                    for item_row in item_rows:
                        matrix["items"].append(
                            {
                                "name": item_row["name"],
                                "note": item_row["note"] or "",
                                "used": bool(item_row["used"]),
                            }
                        )
                    template["matrices"].append(matrix)
                group["templates"].append(template)
            config["groups"].append(group)
        return config


def migrate_style_maintenance_to_db(state: dict) -> bool:
    config = state.get("style_maintenance", {})
    groups = config.get("groups", []) if isinstance(config, dict) else []
    if groups:
        save_style_maintenance_to_db(config)
        state["style_maintenance"] = {}
        return True
    return False


def migrate_identity_options_to_db(state: dict) -> bool:
    ensure_matrix_db()
    changed = False
    for role in state.get("roles", []):
        role_id = role.get("id", "")
        identity_options = role.get("identity_options", {})
        if not role_id or not isinstance(identity_options, dict):
            continue
        for identity_id, rows in list(identity_options.items()):
            if isinstance(rows, list) and rows:
                save_identity_options_to_db(role_id, identity_id, rows)
                changed = True
        role["identity_options"] = {}
    if changed:
        set_db_metadata_value("identity_options_migrated_at", datetime.now().isoformat(timespec="seconds"))
    return changed


def default_character_identity_records() -> list[dict]:
    return [{"id": identity_id, "label": label} for identity_id, label in CHARACTER_IDENTITIES]


def clone_identity_rows(rows: list[dict], target_identity_id: str) -> list[dict]:
    cloned = []
    for index, row in enumerate(rows, start=1):
        new_row = copy.deepcopy(row)
        if new_row.get("module") == "character":
            new_row["role_scope"] = target_identity_id
        if new_row.get("option_id"):
            new_row["option_id"] = f"{target_identity_id}_{new_row.get('dimension_id', 'dimension')}_{index}"
        if new_row.get("value_key"):
            new_row["value_key"] = f"{target_identity_id}_{new_row.get('dimension_id', 'dimension')}_{index}"
        cloned.append(new_row)
    return cloned


def normalize_management_status_defaults(state: dict) -> None:
    """Default missing management statuses to enabled without overriding disabled records."""
    status_specs = (
        ("fixed_style_templates", "enabled", True),
        ("wechat_accounts", "enabled", True),
        ("users", "enabled", True),
        ("article_prompts", "enabled", True),
        ("storyboard_prompt_rules", "enabled", True),
        ("title_library", "status", "启用"),
    )
    for collection_key, status_key, default in status_specs:
        records = state.get(collection_key)
        if not isinstance(records, list):
            continue
        changed = False
        for record in records:
            if not isinstance(record, dict):
                continue
            if status_key not in record or record.get(status_key) in (None, ""):
                record[status_key] = default
                changed = True
        if changed:
            save_db_collection(collection_key, records)

    # Account-level character features are intentionally free-form rather than
    # tied to the retired character-maintenance screens. Backfill the field
    # on existing SQLite rows so exports and subsequent edits remain uniform.
    accounts = state.get("wechat_accounts")
    if isinstance(accounts, list):
        changed = False
        style_by_name = {
            str(item.get("name", "")).strip(): item
            for item in state.get("fixed_style_templates", [])
            if isinstance(item, dict) and str(item.get("name", "")).strip()
        }
        for account in accounts:
            if not isinstance(account, dict):
                continue
            if "character_feature" not in account or account.get("character_feature") is None:
                account["character_feature"] = ""
                changed = True
            if "remove_ai" not in account or account.get("remove_ai") in (None, ""):
                # Preserve the pre-migration behavior once: the old switch
                # lived on the selected style, so seed the account switch from
                # that value. New accounts default to disabled below.
                style = style_by_name.get(str(account.get("style_name", "")).strip(), {})
                value = style.get("remove_ai", False)
                if isinstance(value, str):
                    value = value.strip().lower() in {"是", "true", "1", "yes", "y", "on"}
                account["remove_ai"] = bool(value)
                changed = True
        if changed:
            save_db_collection("wechat_accounts", accounts)

    # The source of truth is now the account record. Remove the retired style
    # field from every style row so it cannot reappear in the management UI or
    # be mistaken for a global switch on a future import/export.
    styles = state.get("fixed_style_templates")
    if isinstance(styles, list):
        style_changed = False
        for style in styles:
            if isinstance(style, dict) and "remove_ai" in style:
                style.pop("remove_ai", None)
                style_changed = True
        if style_changed:
            save_db_collection("fixed_style_templates", styles)


def title_consumption_key(value: object) -> str:
    """Return a stable global identity for a title, ignoring whitespace/case."""
    return re.sub(r"\s+", "", str(value or "")).casefold()


def title_record_used(value: object) -> bool:
    """Normalize the several boolean spellings accepted by Excel imports."""
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    return str(value or "").strip().lower() in {"是", "启用", "已用", "使用", "true", "1", "yes", "y", "on"}


def normalize_title_consumption(state: dict) -> None:
    """Initialize title-use metadata and absorb historical successful works.

    A title is a global resource, so duplicate title-library rows are marked
    together when one normalized title has already produced a successful work.
    """
    titles = state.get("title_library")
    if not isinstance(titles, list):
        return
    successful_keys = {
        title_consumption_key(item.get("title"))
        for item in state.get("generated_works", [])
        if isinstance(item, dict) and str(item.get("status", "")).strip() == "成功" and title_consumption_key(item.get("title"))
    }
    changed = False
    used_at_by_key = {}
    for item in state.get("generated_works", []):
        if not isinstance(item, dict) or str(item.get("status", "")).strip() != "成功":
            continue
        key = title_consumption_key(item.get("title"))
        if key:
            used_at_by_key.setdefault(key, str(item.get("updated_at", "") or "").strip())
    consumed_keys = set(successful_keys)
    for record in titles:
        if not isinstance(record, dict):
            continue
        key = title_consumption_key(record.get("title"))
        if not key:
            continue
        currently_used = title_record_used(record.get("used")) or bool(str(record.get("used_at", "") or "").strip())
        if currently_used:
            consumed_keys.add(key)
        if record.get("used") is not currently_used:
            record["used"] = currently_used
            changed = True
        if currently_used and not str(record.get("used_at", "") or "").strip():
            timestamp = used_at_by_key.get(key) or datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            record["used_at"] = timestamp
            changed = True
        # The management list exposes the user-facing lifecycle state. Keep
        # it synchronized with the internal one-time consumption marker.
        if currently_used and str(record.get("status", "启用")).strip() != "停用":
            record["status"] = "停用"
            changed = True
    # A title is globally consumable. Mark all duplicate rows consistently.
    for record in titles:
        if not isinstance(record, dict):
            continue
        key = title_consumption_key(record.get("title"))
        if key in consumed_keys and not title_record_used(record.get("used")):
            record["used"] = True
            record["used_at"] = used_at_by_key.get(key) or datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            changed = True
        if key in consumed_keys and str(record.get("status", "启用")).strip() != "停用":
            record["status"] = "停用"
            changed = True
    if changed:
        save_db_collection("title_library", titles)


def normalize_style_character_scheme(value: object) -> str:
    """Keep only character appearance, clothing, accessory, and color cues."""
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if not text:
        return ""
    appearance_terms = (
        "人物", "角色", "外貌", "脸", "面部", "五官", "眼", "眉", "鼻", "嘴", "唇", "耳", "发型", "头发", "发色",
        "肤色", "皮肤", "脸型", "身材", "体型", "身形", "体态", "身高", "年龄", "男", "女", "少年", "少女", "孩童",
        "老人", "青年", "胡子", "眼镜", "表情", "发髻", "辫", "马尾", "短发", "长发",
    )
    clothing_terms = (
        "穿着", "服装", "服饰", "衣服", "上衣", "外套", "衬衫", "T恤", "毛衣", "卫衣", "裙", "裤", "短裤", "长裤",
        "鞋", "靴", "袜", "帽", "围巾", "领带", "袖", "领口", "制服", "西装", "旗袍", "汉服", "工装", "牛仔",
        "背心", "睡衣", "包袋", "背包", "首饰", "耳环", "项链", "手链", "戒指", "配饰",
    )
    color_terms = (
        "颜色", "色彩", "配色", "色调", "色号", "#", "黑", "白", "灰", "红", "蓝", "绿", "黄", "紫", "粉", "橙",
        "棕", "褐", "米", "金", "银", "青", "靛", "暖色", "冷色",
    )
    scene_noise = ("画面", "构图", "背景", "留白", "分镜", "镜头", "光影", "线条", "笔触", "质感", "版式", "比例", "对称", "组合", "识别点", "禁止", "不要")
    units = [part.strip(" \t\r\n，,；;。！？!?：:") for part in re.split(r"[\r\n。！？!?；;，,]+", text)]
    kept = []
    for unit in units:
        if len(unit) < 2:
            continue
        has_appearance = any(term in unit for term in appearance_terms)
        has_clothing = any(term in unit for term in clothing_terms)
        has_color = any(term in unit for term in color_terms)
        if not (has_appearance or has_clothing or has_color):
            continue
        # Color-only clauses about backgrounds, composition, or line work are
        # style constraints, not stable character identity information.
        if has_color and not (has_appearance or has_clothing) and any(term in unit for term in scene_noise):
            continue
        if unit not in kept:
            kept.append(unit)
    return "；".join(kept)


def normalize_style_character_scheme_v2(value: object) -> str:
    """Keep character identity clauses and reject mixed scene/layout clauses."""
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    if not text:
        return ""
    appearance_terms = (
        "人物", "角色", "外貌", "脸", "面部", "五官", "眼", "眉", "鼻", "嘴", "唇", "耳", "发型", "头发", "发色",
        "肤色", "皮肤", "脸型", "身材", "体型", "身形", "体态", "身高", "年龄", "男", "女", "少年", "少女", "孩童",
        "老人", "青年", "胡子", "眼镜", "表情", "发髻", "辫", "马尾", "短发", "长发",
    )
    clothing_terms = (
        "穿着", "服装", "服饰", "衣服", "上衣", "外套", "衬衫", "T恤", "毛衣", "卫衣", "裙", "裤", "短裤", "长裤",
        "鞋", "靴", "袜", "帽", "围巾", "领带", "袖", "领口", "制服", "西装", "旗袍", "汉服", "工装", "牛仔",
        "背心", "睡衣", "包袋", "背包", "首饰", "耳环", "项链", "手链", "戒指", "配饰",
    )
    color_terms = (
        "颜色", "色彩", "配色", "色调", "色号", "黑", "白", "灰", "红", "蓝", "绿", "黄", "紫", "粉", "橙",
        "棕", "褐", "米", "金", "银", "青", "靛", "暖色", "冷色", "低饱和",
    )
    # These clauses belong to the style prompt even when they also mention a
    # person.  Splitting before filtering prevents phrases such as
    # “对白放在人物侧上方” from remaining in 人物方案.
    scene_terms = (
        "构图", "留白", "线条", "笔触", "画面", "背景", "分镜", "镜头", "光影", "版式", "对白", "对话", "标题",
        "文字", "字体", "气泡", "动作", "视线", "道具", "场景", "主题", "笑点", "地面", "空间", "同一组图",
        "每幅", "不遮挡", "不铺满", "区域", "位置", "上方", "下方", "侧边", "裁切", "安全边距", "不改变",
        "识别点", "比例", "只改变",
    )
    units = [part.strip(" \t\r\n，,；;。！？!?：:") for part in re.split(r"[\r\n。！？!?；;，,]+", text)]
    kept = []
    for unit in units:
        if len(unit) < 2 or any(term in unit for term in scene_terms):
            continue
        if not any(term in unit for term in appearance_terms + clothing_terms + color_terms):
            continue
        if unit not in kept:
            kept.append(unit)
    return "；".join(kept)


def migrate_character_scheme_constraints_v2(state: dict) -> None:
    """Re-split mixed character/style clauses using the stricter v2 rules."""
    if db_metadata_value("character_scheme_constraints_moved_v2") == "done":
        return
    templates = state.get("fixed_style_templates")
    if not isinstance(templates, list):
        set_db_metadata_value("character_scheme_constraints_moved_v2", "done")
        return
    backups = sorted(
        BUNDLE_DIR.glob("picfactory_matrix.db.bak*"),
        key=lambda path: path.stat().st_mtime,
        reverse=True,
    )
    source_by_key = {}
    if backups:
        try:
            with sqlite3.connect(str(backups[0])) as conn:
                rows = conn.execute(
                    "SELECT payload FROM app_collections WHERE namespace = 'fixed_style_templates'"
                ).fetchall()
            for row in rows:
                try:
                    value = json.loads(row[0])
                except (TypeError, ValueError, json.JSONDecodeError):
                    continue
                if isinstance(value, dict):
                    for key in (value.get("uuid"), value.get("style_id"), value.get("name")):
                        if str(key or "").strip():
                            source_by_key[str(key).strip()] = value
        except Exception:
            source_by_key = {}
    changed = False
    for current in templates:
        if not isinstance(current, dict):
            continue
        source = next(
            (source_by_key.get(str(current.get(key, "")).strip()) for key in ("uuid", "style_id", "name")
             if source_by_key.get(str(current.get(key, "")).strip())),
            None,
        )
        original = str((source or current).get("character_scheme", "") or "").strip()
        cleaned = normalize_style_character_scheme_v2(original)
        original_units = [
            item.strip(" \t\r\n，,；;。！？!?：:")
            for item in re.split(r"[\r\n。！？!?；;，,]+", original)
        ]
        kept_units = {item.strip() for item in cleaned.split("；") if item.strip()}
        discarded = [item for item in original_units if len(item) >= 2 and item not in kept_units]
        if str(current.get("character_scheme", "") or "").strip() != cleaned:
            current["character_scheme"] = cleaned
            changed = True
        if discarded:
            content = str(current.get("content", "") or "").strip()
            existing = set(content.split("画风补充约束：", 1)[-1].split("；")) if "画风补充约束：" in content else set()
            additions = [item for item in discarded if item not in existing and item not in content]
            if additions:
                moved = "画风补充约束：" + "；".join(additions)
                current["content"] = f"{content}\n{moved}".strip()
                current["full_prompt"] = current["content"]
                changed = True
    if changed:
        save_db_collection("fixed_style_templates", templates)
    set_db_metadata_value("character_scheme_constraints_moved_v2", "done")


