def move_style_constraints_from_character_scheme(state: dict) -> None:
    """Move discarded style/layout clauses from the pre-cleanup DB backup."""
    if db_metadata_value("character_scheme_constraints_moved_v1") == "done":
        return
    backups = sorted(
        BUNDLE_DIR.glob("picfactory_matrix.db.bak*"),
        key=lambda path: path.stat().st_mtime,
        reverse=True,
    )
    if not backups:
        set_db_metadata_value("character_scheme_constraints_moved_v1", "done")
        return
    source_records = []
    try:
        with sqlite3.connect(str(backups[0])) as conn:
            rows = conn.execute(
                "SELECT payload FROM app_collections WHERE namespace = 'fixed_style_templates'"
            ).fetchall()
        source_records = []
        for row in rows:
            try:
                value = json.loads(row[0])
            except (TypeError, ValueError, json.JSONDecodeError):
                continue
            if isinstance(value, dict):
                source_records.append(value)
    except Exception:
        source_records = []
    current_records = state.get("fixed_style_templates")
    if not source_records or not isinstance(current_records, list):
        set_db_metadata_value("character_scheme_constraints_moved_v1", "done")
        return
    changed = False
    for current in current_records:
        if not isinstance(current, dict):
            continue
        source = next(
            (
                item for item in source_records
                if str(item.get("uuid", "")).strip() == str(current.get("uuid", "")).strip()
                or str(item.get("name", "")).strip() == str(current.get("name", "")).strip()
            ),
            None,
        )
        if not source:
            continue
        original = str(source.get("character_scheme", "") or "").strip()
        visual = normalize_style_character_scheme(original)
        visual_units = {part.strip() for part in visual.split("；") if part.strip()}
        discarded = []
        for part in [item.strip(" \t\r\n，,；;。！？!?") for item in re.split(r"[\r\n。！？!?；;，,]+", original)]:
            if len(part) >= 2 and part not in visual_units and part not in discarded:
                discarded.append(part)
        if discarded:
            content = str(current.get("content", "") or "").strip()
            moved = "画风补充约束：" + "；".join(discarded)
            if moved not in content:
                current["content"] = f"{content}\n{moved}".strip()
                current["full_prompt"] = current["content"]
                changed = True
    if changed:
        save_db_collection("fixed_style_templates", current_records)
    set_db_metadata_value("character_scheme_constraints_moved_v1", "done")


def ensure_reference_style_template(state: dict) -> None:
    """Seed the hand-drawn dialogue-comic style based on the supplied reference once."""
    templates = state.get("fixed_style_templates")
    if not isinstance(templates, list):
        set_db_metadata_value("reference_dialogue_comic_style_v1", "done")
        return
    style_id = "STYLE-DIALOGUE-COMIC-001"
    reference_character_scheme = (
        "脸型、发型、眉眼和嘴部表情清楚；服装以日常上衣、衬衫、外套或宽松裤装为主，"
        "褶皱少而有辨识度；服装主色跟随当前画面的单一强调色，可替换为其他低饱和颜色；"
        "配饰和发型只保留少量识别点。"
    )
    existing_reference = next(
        (
            item for item in templates
            if isinstance(item, dict)
            and (str(item.get("style_id", "")).strip() == style_id
                 or str(item.get("name", "")).strip() == "白底手绘对话漫画")
        ),
        None,
    )
    if db_metadata_value("reference_dialogue_comic_style_v1") == "done":
        if existing_reference and str(existing_reference.get("character_scheme", "")).strip() != reference_character_scheme:
            existing_reference["character_scheme"] = reference_character_scheme
            content = str(existing_reference.get("content", "") or "").strip()
            moved = "画风补充约束：人物采用简化Q版或轻扁平比例；五官线条简洁但能表达害羞、得意、惊讶或认真等情绪"
            if moved not in content:
                existing_reference["content"] = f"{content}\n{moved}".strip()
            existing_reference["full_prompt"] = existing_reference["content"]
            save_db_collection("fixed_style_templates", templates)
        return
    if not any(
        isinstance(item, dict)
        and (str(item.get("style_id", "")).strip() == style_id
             or str(item.get("name", "")).strip() == "白底手绘对话漫画")
        for item in templates
    ):
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        templates.append({
            "style_id": style_id,
            "name": "白底手绘对话漫画",
            "style_category": "竖版简笔漫画",
            "content": (
                "以竖版社交媒体漫画为基底，采用高留白的白色画布和极简手绘叙事。"
                "画面上方建立清晰的文字标题区：第一行使用粗黑无衬线大字呈现核心观点，"
                "下方可用较细的副标题补充语气或反差；标题与正文之间保留明显呼吸空间。"
                "画面中段使用带尖角或不规则爆炸边的手绘对白气泡，承载一句短、口语化、"
                "有明确态度和笑点的对白；对白与人物动作形成因果关系，文字必须清晰可读。"
                "主体人物放在画面下半部或偏下区域，以单一明确动作承接标题和对白，"
                "构图采用上下分区、轻微偏心和大面积留白，避免背景抢夺文字与人物的注意力。"
                "线条使用黑色或深灰色略带手绘抖动的细线，轮廓线轻重自然，局部允许不完全闭合；"
                "阴影只用少量短线或淡色块提示体积，不做厚重渲染。"
                "整体像一张可快速阅读的观点漫画：标题先抓眼，对白制造反差，动作完成叙事。"
            ),
            "color_scheme": (
                "背景以纯白或暖白为主（约80%-95%）；文字和轮廓使用黑色/深灰。"
                "强调色只保留1种低饱和色，用于标题徽章、人物服装或局部提示，默认靛蓝；"
                "允许按主题替换为砖红、墨绿、橙黄或青蓝，但同一张图只使用一种主强调色，"
                "避免渐变和多色堆叠。人物肤色保持自然暖白，腮红或情绪提示使用极少量淡色。"
            ),
            "character_scheme": (
                reference_character_scheme
            ),
            "size_params": (
                "竖版4:5或3:4；标题区约占上方25%-32%，对白区约占中段15%-25%，"
                "人物主体约占下方35%-50%；四周保留安全边距，中文标题和对白不得贴边或被裁切。"
            ),
            "forbidden_items": (
                "禁止写实摄影、3D渲染、复杂场景背景、密集装饰、厚重渐变、过多颜色、"
                "复杂透视和大面积阴影；禁止让对白气泡遮挡人物五官或关键动作，"
                "禁止标题/对白乱码、错字、无意义英文、Logo、水印、边缘裁切和多余人物。"
            ),
            "full_prompt": "",
            "ai_density": "",
            "ai_grade": "",
            "enabled": True,
            "track": "观点漫画/公众号配图",
            "recommendation": "推荐",
            "note": "根据参考图提炼；强调色可按主题替换。",
            "uuid": str(uuid.uuid4()),
            "updated_at": now,
        })
        templates[-1]["full_prompt"] = templates[-1]["content"]
        save_db_collection("fixed_style_templates", templates)
    set_db_metadata_value("reference_dialogue_comic_style_v1", "done")


def ensure_workplace_article_prompt(state: dict) -> None:
    """Seed the workplace-comic article prompt and link workplace accounts.

    Article prompts live in SQLite, so this migration is deliberately
    idempotent.  Existing custom prompt text is preserved; only accounts that
    are blank or still point at the family template are switched to the new
    workplace template.
    """
    prompts = state.get("article_prompts")
    if not isinstance(prompts, list):
        return
    template_name = "职场漫画"
    existing = next(
        (item for item in prompts if isinstance(item, dict) and str(item.get("template_name", "")).strip() == template_name),
        None,
    )
    if existing is None:
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        detail = (
            "你是一名职场关系漫画文章策划。根据输入标题，识别标题中真实出现的职场人物关系、工作场景、冲突触发点、前后变化和情绪反差，"
            "只围绕标题已经提供的信息展开，不擅自添加公司名称、行业、职位、收入、人物年龄或背景。\n\n"
            "请把标题改编成适合连续漫画的文章结构。优先使用办公室、工位、会议室、茶水间、客户沟通、汇报、打卡、加班、群聊、交接和离职等日常职场场景，"
            "但只有标题能够支持的场景才可以使用。每一条都必须包含可以直接画出来的动作、表情、站位、物品或一句自然对白；不要只写抽象结论。\n\n"
            "默认输出 5 条编号主题。若标题明确要求其他数量，按标题数量执行；没有明确数量时保持 5 条。每条主题都要从标题的不同角度推进，"
            "可以使用初入职场与熟悉以后、会议前与会议后、犯错时与被认可时、同事关系变化、上下级相处、客户沟通和离开团队等对比，"
            "但不得为了凑数重复同一件事。\n\n"
            "固定输出格式：\n"
            "总标题：原始标题\n"
            "1. 主题：具体、短而完整的职场主题\n"
            "   画面：具体地点、人物动作、表情、道具、对白或结果\n"
            "2. 主题：具体、短而完整的职场主题\n"
            "   画面：具体地点、人物动作、表情、道具、对白或结果\n"
            "依次编号，不要漏项。主题句应适合作为单张图片顶部的文案；画面描述供后续分镜 Prompt 使用。\n\n"
            "要求：人物称谓使用同事、主管、领导、客户、下属、前辈、新人等标题中已有的关系；对白口语自然，控制在 1 至 2 句；"
            "每条至少有一个可视化动作和一个明确情绪。不要写成工作报告、鸡汤或抽象职场道理，不要输出开场白、总结、解释或与标题无关的建议。\n\n"
            "禁止：擅自增加标题没有的职位、公司制度、行业背景、地点和重大事件；把‘压力大’‘很无奈’‘关系很好’等空泛词直接当画面；"
            "重复同一动作或同一对白；使用乱码、无意义英文、Logo、水印或多余人物。完成后只保留总标题和编号主题内容。"
        )
        existing = {
            "uuid": str(uuid.uuid4()),
            "prompt_type": "职场漫画",
            "template_name": template_name,
            "detail": detail,
            "note": "根据家庭关系漫画模板扩展的职场连续漫画文章提示词。",
            "enabled": True,
            "updated_at": now,
        }
        prompts.append(existing)
        save_db_collection("article_prompts", prompts)

    # Older seeded templates instructed the model to always produce five
    # themes.  Keep their formatting rules, but make the number of themes
    # follow the title's actual narrative structure.
    flexible_replacements = {
        '标题中出现“几种、几个、几次”时，默认输出5条。': '标题中出现“几种、几个、几次”时，根据标题实际内容灵活确定主题数量。',
        '标题没有数量时，默认输出5条。': '标题没有数量时，按标题可拆分的实际叙事节点灵活确定主题数量。',
        '标题中出现“几种、几个、几次”，默认输出5条。': '标题中出现“几种、几个、几次”时，根据标题实际内容灵活确定主题数量。',
        '标题没有明确数量时，默认输出5条。': '标题没有明确数量时，按标题可拆分的实际叙事节点灵活确定主题数量。',
        '默认输出 5 条编号主题。若标题明确要求其他数量，按标题数量执行；没有明确数量时保持 5 条。': '编号主题数量不设固定值：标题明确要求数量时按标题执行，没有明确数量时按实际叙事节点灵活确定，不为凑数重复内容。',
    }
    prompt_changed = False
    for prompt in prompts:
        if not isinstance(prompt, dict):
            continue
        detail = str(prompt.get("detail", "") or prompt.get("content", ""))
        updated_detail = detail
        for old_text, new_text in flexible_replacements.items():
            updated_detail = updated_detail.replace(old_text, new_text)
        if updated_detail != detail:
            prompt["detail"] = updated_detail
            prompt["updated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            prompt_changed = True
    if prompt_changed:
        save_db_collection("article_prompts", prompts)

    # Category-specific defaults keep newly imported accounts from accidentally
    # using an empty or unrelated global prompt. Preserve unrelated custom
    # choices when an account already has an explicit template.
    accounts = state.get("wechat_accounts")
    if not isinstance(accounts, list):
        return
    changed = False
    for account in accounts:
        if not isinstance(account, dict):
            continue
        category = str(account.get("title_category", "")).strip()
        current = str(account.get("article_prompt", "")).strip()
        if category == "职场" and (not current or current == "家长里短对比漫画"):
            account["article_prompt"] = template_name
            account["updated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            changed = True
        elif category == "家长里短" and not current:
            account["article_prompt"] = "家长里短对比漫画"
            account["updated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            changed = True
    if changed:
        save_db_collection("wechat_accounts", accounts)


def ensure_funny_article_prompt(state: dict) -> None:
    """Seed the title-free continuous funny-comic article prompt."""
    prompts = state.get("article_prompts")
    if not isinstance(prompts, list):
        return
    template_name = "搞笑漫画"
    if any(
        isinstance(item, dict)
        and str(item.get("template_name", "")).strip() == template_name
        for item in prompts
    ):
        return
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    detail = (
        "你是一名搞笑漫画分镜策划。参考现有家长里短对比漫画和职场漫画的写法，"
        "从输入标题中提炼真实的生活冲突、误会、反差、动作节奏和笑点，只围绕标题能够支持的内容创作。\n\n"
        "本模板不写文章主题，不生成总标题，也不生成任何图片标题。只输出可直接交给连续生图流程的画面结构："
        "按故事实际需要拆成连续的 3 至 8 个画面，每个画面写清人物、动作、表情、场景、道具、对白和笑点推进。"
        "画面数量由故事结构决定，不要为了凑数重复或补写。每个画面必须能独立绘制，同时与前后画面保持人物、服装、道具和空间连续。\n\n"
        "严格输出格式（不要输出格式说明、开场白、总结或标题）：\n"
        "画面1：地点、人物动作、表情、对白和笑点\n"
        "画面2：地点、人物动作、表情、对白和笑点\n"
        "依次编号，编号从 1 开始连续递增。画面内容可以包含对白，但不要添加‘主题：’、‘标题：’、‘画面标题：’等标签。"
        "不要输出 Markdown、Logo、水印、无意义英文或与标题无关的背景设定。"
    )
    prompts.append({
        "uuid": str(uuid.uuid4()),
        "prompt_type": template_name,
        "template_name": template_name,
        "detail": detail,
        "note": "只生成连续画面结构，不生成主题和图片标题。",
        "enabled": True,
        "updated_at": now,
    })
    save_db_collection("article_prompts", prompts)


def ensure_comment_prompt_templates(state: dict) -> None:
    """Seed category-bound comment prompts once, with a universal fallback."""
    prompts = state.get("comment_prompts")
    if not isinstance(prompts, list):
        return
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    changed = False
    default_name = "初始留言提示词"
    default_detail = (
        "你是公众号评论区互动语编辑。请根据标题生成一句自然、简洁、与内容相关的结尾互动语，"
        "引导读者分享经历或看法。只输出一句话，不要输出标题、编号、总结、标签、表情、引号或解释。\n"
        "【标题】${标题}\n【标题分类】${标题分类}\n"
    )
    if not any(isinstance(item, dict) and str(item.get("template_name", "")).strip() == default_name for item in prompts):
        prompts.append({
            "uuid": str(uuid.uuid4()),
            "prompt_type": "通用",
            "category": "",
            "template_name": default_name,
            "detail": default_detail,
            "note": "未匹配标题分类时使用的初始留言提示词。",
            "enabled": True,
            "updated_at": now,
        })
        changed = True

    # Existing title categories receive editable templates during the
    # one-time migration. Categories added later intentionally fall back to
    # the initial template until the user creates a dedicated one.
    if db_metadata_value("comment_prompt_templates_v1") != "done":
        categories = sorted({
            str(item.get("category", "")).strip()
            for item in state.get("title_library", [])
            if isinstance(item, dict) and str(item.get("category", "")).strip()
        })
        category_hints = {
            "家长里短": "围绕家庭成员、亲戚邻里或日常家长里短，引导读者分享自己家是否也遇到过类似情况。",
            "职场": "围绕同事、领导、客户或工作现场的具体反差，引导读者分享自己是否遇到过类似经历。",
            "搞笑漫画": "围绕标题里的误会、反差或离谱笑点，引导读者分享自己遇到过的更搞笑情况。",
        }
        for category in categories:
            if any(isinstance(item, dict) and str(item.get("category", "")).strip() == category for item in prompts):
                continue
            hint = category_hints.get(category, f"围绕‘{category}’分类标题的具体内容，引导读者分享自己的类似经历或看法。")
            prompts.append({
                "uuid": str(uuid.uuid4()),
                "prompt_type": "分类留言",
                "category": category,
                "template_name": f"{category}留言提示词",
                "detail": (
                    "你是公众号评论区互动语编辑。" + hint + "\n"
                    "只输出一句自然、简洁的问句或邀请语，不要输出标题、编号、总结、标签、表情、引号或解释。\n"
                    "【标题】${标题}\n【标题分类】${标题分类}\n"
                ),
                "note": f"标题分类‘{category}’专用留言提示词。",
                "enabled": True,
                "updated_at": now,
            })
            changed = True
        set_db_metadata_value("comment_prompt_templates_v1", "done")
    if changed:
        save_db_collection("comment_prompts", prompts)


def normalize_state() -> dict:
    ensure_matrix_db()
    base_options = load_base_options()
    global_options = [row for row in base_options if row.get("module") != "character"]
    global_options.extend(copy.deepcopy(DEFAULT_RULE_OPTIONS))
    if STATE_PATH.exists():
        state = json.loads(STATE_PATH.read_text(encoding="utf-8-sig"))
    else:
        state = {"active_role_id": "yan", "roles": []}
    hydrate_db_collections(state)
    hydrate_db_settings(state)
    # The old image-prompt module is removed. Keep its records under the new
    # rule collection during the one-time migration, then delete the legacy
    # namespace so it cannot reappear after a restart.
    legacy_rules = load_db_collection("reference_image_prompts") or state.get("reference_image_prompts", [])
    if legacy_rules and not state.get("storyboard_prompt_rules"):
        state["storyboard_prompt_rules"] = legacy_rules
        save_db_collection("storyboard_prompt_rules", legacy_rules)
    state.pop("reference_image_prompts", None)
    remove_db_collection("reference_image_prompts")
    # Account/title collections are intentionally kept in SQLite through the
    # shared collection layer.  Empty defaults keep the UI usable on a fresh DB.
    for collection_key in (
        "wechat_accounts",
        "title_library",
        "users",
        "article_prompts",
        "comment_prompts",
        "storyboard_prompt_rules",
        "generated_works",
    ):
        if not isinstance(state.get(collection_key), list):
            state[collection_key] = []
    # Title consumption is global across accounts. Migrate successful legacy
    # works into the title pool before any new account task is assembled.
    normalize_title_consumption(state)
    account_generation_config = state.get("account_generation_config")
    if isinstance(account_generation_config, dict):
        # Migrate the retired manual scene-count field out of persisted config.
        account_generation_config.pop("scene_count", None)
    ensure_workplace_article_prompt(state)
    ensure_funny_article_prompt(state)
    ensure_comment_prompt_templates(state)
    if not state["storyboard_prompt_rules"]:
        state["storyboard_prompt_rules"] = [{
            "uuid": str(uuid.uuid4()),
            "template_name": "默认连续分镜规则",
            "prompt_content": (
                "你是一名连续漫画分镜导演。请将输入文章拆解为连续、可直接用于生图的分镜 Prompt。\n"
                "画风详情：${画风}\n人物方案：${人物}\n标题：${标题}\n文章：${文章}\n"
                "请生成 ${分镜数量} 个分镜，严格使用以下格式：\n"
                "场景画面1：画面标题\n完整图片 Prompt\n"
                "场景画面2：画面标题\n完整图片 Prompt\n"
                "先完整理解文章，再依据文章真实出现的人物、事件、关系变化、对白、动作和转折，"
                "动态挑选最有代表性的 ${分镜数量} 个叙事节点；不要按句子机械平均切分，"
                "不要套用固定的六宫格主题，不要添加文章没有的关键事件。分镜之间要有自然的先后关系，"
                "即使文章段落长短不同，也要优先保留能独立成画并推动故事的节点。\n"
                "每个图片 Prompt 必须描述明确的主体、动作、表情、环境、镜头和光线；"
                "所有分镜必须保持人物外观、服装、道具、空间、色彩和画风一致。"
            ),
            "note": "系统默认模板，可按需编辑。",
            "enabled": True,
            "updated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        }]
        save_db_collection("storyboard_prompt_rules", state["storyboard_prompt_rules"])
    else:
        # Keep the built-in rule aligned with the account workflow: the scene
        # count stays fixed, while the six narrative nodes come from the
        # generated article instead of a hard-coded six-panel sequence.
        default_rule_changed = False
        for rule in state["storyboard_prompt_rules"]:
            if not isinstance(rule, dict) or str(rule.get("template_name", "")).strip() != "默认连续分镜规则":
                continue
            prompt_content = str(rule.get("prompt_content", "") or rule.get("content", "")).strip()
            if "动态挑选" not in prompt_content:
                prompt_content = (
                    f"{prompt_content}\n"
                    "先完整理解文章，再依据文章真实出现的人物、事件、关系变化、对白、动作和转折，"
                    "动态挑选最有代表性的 ${分镜数量} 个叙事节点；不要按句子机械平均切分，"
                    "不要套用固定的六宫格主题，不要添加文章没有的关键事件。分镜之间要有自然的先后关系，"
                    "优先保留能独立成画并推动故事的节点。"
                ).strip()
                rule["prompt_content"] = prompt_content
                rule["updated_at"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                default_rule_changed = True
        if default_rule_changed:
            save_db_collection("storyboard_prompt_rules", state["storyboard_prompt_rules"])
    normalize_management_status_defaults(state)
    normalize_style_character_schemes(state)
    move_style_constraints_from_character_scheme(state)
    migrate_character_scheme_constraints_v2(state)
    migrate_character_scheme_constraints_v3(state)
    migrate_character_scheme_constraints_v4(state)
    ensure_reference_style_template(state)

    # Preserve a legacy fixed-style selection once, then remove all injection
    # controls so they cannot reappear on the next save.
    style_names = {
        str(item.get("name", "")).strip()
        for item in state.get("fixed_style_templates", [])
        if isinstance(item, dict) and str(item.get("name", "")).strip()
    }
    for config_key in ("storyboard_config", "writing_config", "batch_writing_config", "image_batch_config", "illustration_batch_config"):
        config = state.get(config_key)
        if isinstance(config, dict) and not str(config.get("style_name", "") or "").strip():
            legacy_name = str(config.get("fixed_style_template", "") or "").strip()
            if legacy_name in style_names:
                config["style_name"] = legacy_name
    sanitize_production_style_configs(state)

    if not state.get("character_identities"):
        state["character_identities"] = default_character_identity_records()
    normalized_identities = []
    used_identity_ids = set()
    for index, item in enumerate(state.get("character_identities", []), start=1):
        if isinstance(item, dict):
            identity_id = str(item.get("id", "")).strip()
            label = str(item.get("label", "")).strip()
        else:
            identity_id, label = item
        if not label:
            continue
        if not identity_id:
            identity_id = f"custom_identity_{index}"
        base_identity_id = identity_id
        suffix = 2
        while identity_id in used_identity_ids:
            identity_id = f"{base_identity_id}_{suffix}"
            suffix += 1
        used_identity_ids.add(identity_id)
        normalized_identities.append({"id": identity_id, "label": label})
    if not normalized_identities:
        normalized_identities = default_character_identity_records()
    state["character_identities"] = normalized_identities
    identity_items = [(item["id"], item["label"]) for item in state["character_identities"]]

    if not state.get("roles"):
        state["roles"] = [
            {
                "id": "yan",
                "name": "yan",
                "source_role_id": "",
                "created_at": datetime.now().isoformat(timespec="seconds"),
                "identity_options": {},
                "global_options": copy.deepcopy(global_options),
            }
        ]

    if not any(role["id"] == "yan" for role in state["roles"]):
        state["roles"].insert(
            0,
            {
                "id": "yan",
                "name": "yan",
                "source_role_id": "",
                "created_at": datetime.now().isoformat(timespec="seconds"),
                "identity_options": {},
                "global_options": copy.deepcopy(global_options),
            },
        )

    migrate_identity_options_to_db(state)
    for role in state["roles"]:
        role.setdefault("identity_options", {})
        if "global_options" not in role:
            role["global_options"] = copy.deepcopy(global_options)
        if not any(row.get("module") in GLOBAL_MODULE_CONFIG["rules"]["module_names"] for row in role["global_options"]):
            role["global_options"].extend(copy.deepcopy(DEFAULT_RULE_OPTIONS))
        role["identity_options"] = {}
        for identity_id, _label in identity_items:
            if not identity_options_exist_in_db(role["id"], identity_id):
                base_rows = base_options_for_identity(base_options, identity_id)
                if not base_rows and identity_id not in dict(CHARACTER_IDENTITIES):
                    base_rows = clone_identity_rows(base_options_for_identity(base_options, "female_lead"), identity_id)
                save_identity_options_to_db(role["id"], identity_id, base_rows)
        normalize_option_ratios(role["global_options"])
        continue
        for identity_id, _label in identity_items:
            if identity_id not in role["identity_options"]:
                base_rows = base_options_for_identity(base_options, identity_id)
                if not base_rows and identity_id not in dict(CHARACTER_IDENTITIES):
                    base_rows = clone_identity_rows(base_options_for_identity(base_options, "female_lead"), identity_id)
                role["identity_options"][identity_id] = base_rows
                continue
            filtered = [
                row
                for row in role["identity_options"][identity_id]
                if is_identity_option(row, identity_id)
            ]
            role["identity_options"][identity_id] = filtered or base_options_for_identity(base_options, identity_id)
            normalize_option_ratios(role["identity_options"][identity_id])
        for identity_rows in role["identity_options"].values():
            normalize_option_ratios(identity_rows)
        normalize_option_ratios(role["global_options"])

    if not any(role["id"] == state.get("active_role_id") for role in state["roles"]):
        state["active_role_id"] = "yan"
    if not state.get("build_templates"):
        state["build_templates"] = copy.deepcopy(BUILD_TEMPLATES)
    for template in state["build_templates"]:
        template.setdefault("content", DEFAULT_TEMPLATE_CONTENT)
        template.setdefault("dimensions", [])
        template.setdefault("bound_identity_id", "")
    if not state.get("style_build_templates"):
        state["style_build_templates"] = copy.deepcopy(STYLE_BUILD_TEMPLATES)
    for template in state["style_build_templates"]:
        template.setdefault("content", DEFAULT_TEMPLATE_CONTENT)
        template.setdefault("dimensions", [])
        content = template.get("content", "")
        replacements = {
            "${风格大类}": "${风格}",
            "${画风大类}": "${风格}",
            "${具体画风}": "${画风}",
            "${具体画风模板}": "${画风}",
            "${矩阵}": "${矩阵名}",
        }
        for old_token, new_token in replacements.items():
            content = content.replace(old_token, new_token)
        old_default_contents = {
            "请生成漫画风格描述体。整体风格为${写实程度}${色彩风格}${光影}${漫画界面}。${矩阵名}": "请生成漫画风格描述体。风格为${风格}，画风为${画风}。${矩阵名}",
            "请生成清爽竖版条漫风格描述体，画面采用${写实程度}、${色彩风格}、${光影}。${矩阵名}": "请生成清爽竖版条漫风格描述体。风格为${风格}，画风为${画风}。${矩阵名}",
        }
        template["content"] = old_default_contents.get(content, content)
    migrate_style_maintenance_to_db(state)
    identity_template_defaults = state.setdefault("identity_default_build_templates", {})
    identity_template_names = {template.get("name", "") for template in state["build_templates"]}
    fallback_identity_template = state["build_templates"][0].get("name", "") if state["build_templates"] else ""
    identity_ids = {identity_id for identity_id, _label in identity_items}
    fallback_identity_id = identity_items[0][0] if identity_items else ""
    label_to_identity_id = {label: identity_id for identity_id, label in identity_items}

    def owner_from_template_name(template_name: str) -> str:
        for label, identity_id in label_to_identity_id.items():
            if label and template_name.startswith(f"{label}默认模板"):
                return identity_id
        return ""

    for identity_id, label in identity_items:
        current_default = identity_template_defaults.get(identity_id, "")
        current_owner = owner_from_template_name(current_default)
        preferred_default = next(
            (
                template.get("name", "")
                for template in state["build_templates"]
                if template.get("name", "").startswith(f"{label}默认模板A")
            ),
            "",
        )
        if current_default not in identity_template_names:
            identity_template_defaults[identity_id] = preferred_default or fallback_identity_template
        elif current_owner and current_owner != identity_id and preferred_default:
            identity_template_defaults[identity_id] = preferred_default

    template_default_owner = {
        template_name: identity_id
        for identity_id, template_name in identity_template_defaults.items()
        if identity_id in identity_ids and template_name in identity_template_names
    }

    def infer_template_identity_id(template: dict) -> str:
        template_name = template.get("name", "")
        prefix_owner = owner_from_template_name(template_name)
        if prefix_owner:
            return prefix_owner
        if template_name in template_default_owner:
            return template_default_owner[template_name]
        return ""

    for template in state["build_templates"]:
        inferred_identity_id = infer_template_identity_id(template)
        if inferred_identity_id:
            template["bound_identity_id"] = inferred_identity_id
        elif template.get("bound_identity_id") not in identity_ids:
            template["bound_identity_id"] = fallback_identity_id
    bound_template_names = {}
    for template in state["build_templates"]:
        bound_identity_id = template.get("bound_identity_id", "")
        template_name = template.get("name", "")
        if bound_identity_id in identity_ids and template_name:
            bound_template_names.setdefault(bound_identity_id, []).append(template_name)
    for identity_id in identity_ids:
        names = bound_template_names.get(identity_id, [])
        if not names:
            identity_template_defaults.pop(identity_id, None)
        elif identity_template_defaults.get(identity_id) not in names:
            identity_template_defaults[identity_id] = names[0]
    for identity_id in list(identity_template_defaults):
        if identity_id not in identity_ids:
            identity_template_defaults.pop(identity_id, None)
    return state


def prepare_popup_window(window, parent=None, geometry="960x720", minsize=(800, 560), modal=False):
    """Give application popups enough room and keep the native maximize button."""
    try:
        screen_width = max(640, int(window.winfo_screenwidth()))
        screen_height = max(480, int(window.winfo_screenheight()))
        geometry_match = re.match(r"^(\d+)x(\d+)(.*)$", str(geometry))
        if geometry_match:
            width = min(int(geometry_match.group(1)), screen_width - 80)
            height = min(int(geometry_match.group(2)), screen_height - 100)
            geometry = f"{max(360, width)}x{max(260, height)}{geometry_match.group(3)}"
        min_width = min(int(minsize[0]), max(360, screen_width - 80))
        min_height = min(int(minsize[1]), max(260, screen_height - 100))
        minsize = (min_width, min_height)
    except (tk.TclError, TypeError, ValueError):
        pass
    window.geometry(geometry)
    window.minsize(*minsize)
    window.resizable(True, True)
    if parent is not None:
        window.transient(parent)
    if sys.platform.startswith("win"):
        # Tk can classify transient windows as tool windows, which hides the
        # native maximize button. Explicitly request a normal window frame.
        try:
            window.wm_attributes("-toolwindow", False)
        except tk.TclError:
            pass
    if modal:
        window.grab_set()
    try:
        window.update_idletasks()
    except tk.TclError:
        pass
    if sys.platform.startswith("win"):
        # Windows removes the maximize/minimize style from transient Tk
        # windows. Restore the standard caption buttons and resize frame.
        try:
            import ctypes
            from ctypes import wintypes

            user32 = ctypes.WinDLL("user32", use_last_error=True)
            hwnd = wintypes.HWND(window.winfo_id())
            get_style = user32.GetWindowLongPtrW
            get_style.argtypes = [wintypes.HWND, ctypes.c_int]
            get_style.restype = ctypes.c_ssize_t
            set_style = user32.SetWindowLongPtrW
            set_style.argtypes = [wintypes.HWND, ctypes.c_int, ctypes.c_ssize_t]
            set_style.restype = ctypes.c_ssize_t
            style = get_style(hwnd, -16)  # GWL_STYLE
            style |= 0x00010000 | 0x00020000 | 0x00040000  # MAXIMIZEBOX, MINIMIZEBOX, THICKFRAME
            set_style(hwnd, -16, style)
            user32.SetWindowPos(hwnd, 0, 0, 0, 0, 0, 0x0027)  # frame changed, keep position/size
        except (AttributeError, OSError, tk.TclError, TypeError, ValueError):
            pass
    return window


class TextInputDialog(tk.Toplevel):
    def __init__(self, parent, title: str, prompt: str, initialvalue: str = ""):
        super().__init__(parent)
        self.result = None
        self._normal_geometry = "760x320"
        self.title(title)
        prepare_popup_window(self, parent, self._normal_geometry, (600, 240), modal=True)
        self.configure(bg=COLORS["paper"])

        header = ttk.Frame(self, padding=12, style="Panel.TFrame")
        header.pack(fill="x")
        ttk.Label(header, text=title, font=("Microsoft YaHei", 14, "bold")).pack(side="left")
        ttk.Button(header, text="全屏/还原", command=self.toggle_fullscreen).pack(side="right", padx=(0, 8))
        ttk.Button(header, text="关闭", command=self.cancel).pack(side="right")

        body = ttk.Frame(self, padding=14, style="Panel.TFrame")
        body.pack(fill="both", expand=True)
        ttk.Label(body, text=prompt).pack(anchor="w", pady=(0, 8))
        self.var = tk.StringVar(value=initialvalue)
        entry = ttk.Entry(body, textvariable=self.var)
        entry.pack(fill="x")
        entry.focus_set()

        actions = ttk.Frame(body, style="Panel.TFrame")
        actions.pack(fill="x", pady=(14, 0))
        ttk.Button(actions, text="确定", command=self.ok).pack(side="right")
        ttk.Button(actions, text="取消", command=self.cancel).pack(side="right", padx=8)

        self.bind("<Return>", lambda _event: self.ok())
        self.bind("<Escape>", lambda _event: self.cancel())
        self.bind("<F11>", lambda _event: self.toggle_fullscreen())

    def toggle_fullscreen(self):
        if self.state() == "zoomed":
            self.state("normal")
            self.geometry(self._normal_geometry)
        else:
            self._normal_geometry = self.geometry()
            self.state("zoomed")

    def ok(self):
        self.result = self.var.get()
        self.destroy()

    def cancel(self):
        self.result = None
        self.destroy()


def ask_text(parent, title: str, prompt: str, initialvalue: str = ""):
    dialog = TextInputDialog(parent, title, prompt, initialvalue)
    parent.wait_window(dialog)
    return dialog.result


class ResizableMessageDialog(tk.Toplevel):
    def __init__(self, parent, title: str, message: str, buttons: list[tuple[str, object]], default_result=None):
        super().__init__(parent)
        self.result = default_result
        self._normal_geometry = "900x500"
        self.title(title)
        prepare_popup_window(self, parent, self._normal_geometry, (640, 320), modal=True)
        self.configure(bg=COLORS["paper"])
        self.protocol("WM_DELETE_WINDOW", lambda: self.close(default_result))

        header = ttk.Frame(self, padding=12, style="Panel.TFrame")
        header.pack(fill="x")
        ttk.Label(header, text=title, font=("Microsoft YaHei", 14, "bold")).pack(side="left")
        ttk.Button(header, text="全屏/还原", command=self.toggle_fullscreen).pack(side="right", padx=(0, 8))

        body = ttk.Frame(self, padding=14, style="Panel.TFrame")
        body.pack(fill="both", expand=True)
        message_frame = ttk.Frame(body, style="Panel.TFrame")
        message_frame.pack(fill="both", expand=True)
        text = tk.Text(
            message_frame,
            wrap="word",
            height=6,
            bg=COLORS["white"],
            fg=COLORS["text"],
            relief="solid",
            bd=1,
            font=("Microsoft YaHei", 10),
        )
        text.pack(side="left", fill="both", expand=True)
        scrollbar = ttk.Scrollbar(message_frame, orient="vertical", command=text.yview)
        scrollbar.pack(side="right", fill="y")
        text.configure(yscrollcommand=scrollbar.set)
        text.insert("1.0", message)
        text.configure(state="disabled")

        actions = ttk.Frame(body, style="Panel.TFrame")
        actions.pack(fill="x", pady=(14, 0))
        for label, value in buttons:
            ttk.Button(actions, text=label, command=lambda result=value: self.close(result)).pack(side="right", padx=(8, 0))

        self.bind("<F11>", lambda _event: self.toggle_fullscreen())
        self.bind("<Escape>", lambda _event: self.close(default_result))
        self.focus_set()

    def toggle_fullscreen(self):
        if self.state() == "zoomed":
            self.state("normal")
            self.geometry(self._normal_geometry)
        else:
            self._normal_geometry = self.geometry()
            self.state("zoomed")

    def close(self, result):
        self.result = result
        try:
            self.grab_release()
        except tk.TclError:
            pass
        self.destroy()


class ResizableMessageBox:
    @staticmethod
    def _parent(parent=None):
        if parent is not None:
            return parent
        root = tk._default_root
        if root is None:
            return None
        try:
            focus = root.focus_get()
            if focus is not None:
                return focus.winfo_toplevel()
        except tk.TclError:
            pass
        return root

    @staticmethod
    def _show(title: str, message: str, buttons: list[tuple[str, object]], default_result=None, parent=None):
        parent = ResizableMessageBox._parent(parent)
        dialog = ResizableMessageDialog(parent, title, str(message), buttons, default_result)
        dialog.wait_window()
        if isinstance(parent, tk.Toplevel) and parent.winfo_exists():
            try:
                parent.grab_set()
            except tk.TclError:
                pass
        return dialog.result

    @staticmethod
    def showinfo(title: str, message: str, **kwargs):
        return ResizableMessageBox._show(title, message, [("确定", "ok")], "ok", kwargs.get("parent"))

    @staticmethod
    def showerror(title: str, message: str, **kwargs):
        return ResizableMessageBox._show(title, message, [("确定", "ok")], "ok", kwargs.get("parent"))

    @staticmethod
    def showwarning(title: str, message: str, **kwargs):
        return ResizableMessageBox._show(title, message, [("确定", "ok")], "ok", kwargs.get("parent"))

    @staticmethod
    def askyesno(title: str, message: str, **kwargs) -> bool:
        return bool(
            ResizableMessageBox._show(
                title,
                message,
                [("否", False), ("是", True)],
                False,
                kwargs.get("parent"),
            )
        )

    @staticmethod
    def askyesnocancel(title: str, message: str, **kwargs):
        return ResizableMessageBox._show(
            title,
            message,
            [("取消", None), ("否", False), ("是", True)],
            None,
            kwargs.get("parent"),
        )


messagebox = ResizableMessageBox


class MatrixEditor(tk.Toplevel):
    def __init__(self, app, identity_id: str, identity_label: str, dimension_id: str, dimension_label: str):
        super().__init__(app.root)
        self.app = app
        self.identity_id = identity_id
        self.identity_label = identity_label
        self.dimension_id = dimension_id
        self.dimension_label = dimension_label
        self.selected_index = None
        self._normal_geometry = "1280x820"
        self.matrix_name_var = tk.StringVar(value=dimension_label)
        self.ratio_remaining_var = tk.StringVar(value="启用条目占比剩余额度：100")

        self.title(f"{identity_label} - {dimension_label}")
        prepare_popup_window(self, app.root, self._normal_geometry, (900, 600), modal=True)
        self.configure(bg=COLORS["paper"])
        self.bind("<F11>", lambda _event: self.toggle_fullscreen())
        self.bind("<Escape>", lambda _event: self.exit_fullscreen())

        self._build()
        self.refresh()

    @property
    def rows(self) -> list[dict]:
        return [
            row
            for row in self.app.get_identity_options(self.identity_id)
            if row.get("dimension_id") == self.dimension_id
            or row.get("dimension_label") == self.dimension_label
        ]

    def _build(self):
        header = ttk.Frame(self, padding=12, style="Panel.TFrame")
        header.pack(fill="x")
        ttk.Label(header, text=f"{self.identity_label} / {self.dimension_label}", font=("Microsoft YaHei", 16, "bold")).pack(side="left")
        ttk.Button(header, text="全屏/还原", command=self.toggle_fullscreen).pack(side="right", padx=(0, 8))
        ttk.Button(header, text="关闭", command=self.destroy).pack(side="right")

        actions = ttk.Frame(self, padding=(12, 0, 12, 10), style="Panel.TFrame")
        actions.pack(fill="x")
        ttk.Button(actions, text="新增", command=self.add_row).pack(side="left")
        ttk.Button(actions, text="保存修改", command=self.update_row).pack(side="left", padx=8)
        ttk.Button(actions, text="删除", command=self.delete_row).pack(side="left")
        ttk.Separator(actions, orient="vertical").pack(side="left", fill="y", padx=8)
        ttk.Button(actions, text="导出此矩阵 Excel", command=self.export_matrix).pack(side="left")
        ttk.Button(actions, text="导入此矩阵 Excel", command=self.import_matrix).pack(side="left", padx=8)
        ttk.Button(actions, text="撤回上一版", command=lambda: self.app.undo_last(self.refresh)).pack(side="left")
        ttk.Button(actions, text="保存到本地", command=self.save_matrix_state).pack(side="right")

        body = ttk.Frame(self, padding=(12, 0, 12, 12), style="Panel.TFrame")
        body.pack(fill="both", expand=True)

        name_form = ttk.LabelFrame(body, text="矩阵名称", padding=10, style="TLabelframe")
        name_form.pack(fill="x", pady=(0, 10))
        ttk.Label(name_form, text="名称").pack(side="left", padx=(0, 8))
        ttk.Entry(name_form, textvariable=self.matrix_name_var).pack(side="left", fill="x", expand=True)
        ttk.Button(name_form, text="保存矩阵名称", command=self.rename_matrix).pack(side="left", padx=(8, 0))

        columns = ("label", "ratio", "sub_category", "enabled", "value_key", "notes")
        tree_frame = ttk.Frame(body, style="Panel.TFrame")
        tree_frame.pack(fill="both", expand=True)
        self.tree = ttk.Treeview(tree_frame, columns=columns, show="headings", height=16)
        tree_y_scrollbar = ttk.Scrollbar(tree_frame, orient="vertical", command=self.tree.yview)
        tree_x_scrollbar = ttk.Scrollbar(tree_frame, orient="horizontal", command=self.tree.xview)
        self.tree.configure(yscrollcommand=tree_y_scrollbar.set, xscrollcommand=tree_x_scrollbar.set)
        headings = {
            "label": "选项内容",
            "ratio": "占比",
            "sub_category": "子分类",
            "enabled": "启用",
            "value_key": "值键",
            "notes": "备注",
        }
        widths = {"label": 240, "ratio": 70, "sub_category": 120, "enabled": 60, "value_key": 180, "notes": 260}
        for col in columns:
            self.tree.heading(col, text=headings[col])
            self.tree.column(col, width=widths[col], anchor="w")
        self.tree.grid(row=0, column=0, sticky="nsew")
        tree_y_scrollbar.grid(row=0, column=1, sticky="ns")
        tree_x_scrollbar.grid(row=1, column=0, sticky="ew")
        tree_frame.rowconfigure(0, weight=1)
        tree_frame.columnconfigure(0, weight=1)
        self.tree.bind("<<TreeviewSelect>>", self.on_select)

        form = ttk.LabelFrame(body, text="单项维护", padding=10, style="TLabelframe")
        form.pack(fill="x", pady=(12, 0))

        self.fields = {}
        field_defs = [
            ("label", "选项内容", 0, 0, 44),
            ("ratio", "占比 float", 0, 2, 24),
            ("value_key", "值键", 1, 0, 44),
            ("enabled", "启用 TRUE/FALSE", 1, 2, 24),
            ("sub_category", "子分类", 2, 0, 44),
            ("notes", "备注", 3, 0, 74),
        ]
        for key, label, row, col, width in field_defs:
            ttk.Label(form, text=label).grid(row=row, column=col, sticky="w", padx=(0, 8), pady=5)
            entry = ttk.Entry(form, width=width)
            entry.grid(row=row, column=col + 1, sticky="ew", padx=(0, 16), pady=5)
            self.fields[key] = entry
        ratio_tools = ttk.Frame(form, style="Panel.TFrame")
        ratio_tools.grid(row=4, column=0, columnspan=4, sticky="ew", pady=(8, 0))
        ttk.Label(ratio_tools, textvariable=self.ratio_remaining_var).pack(side="left")
        ttk.Button(ratio_tools, text="占比清零", command=self.clear_ratios).pack(side="right")
        self.fields["ratio"].bind("<KeyRelease>", lambda _event: self.update_ratio_remaining())
        self.fields["enabled"].bind("<KeyRelease>", lambda _event: self.update_ratio_remaining())
        form.columnconfigure(1, weight=1)

    def toggle_fullscreen(self):
        if self.state() == "zoomed":
            self.state("normal")
            self.geometry(self._normal_geometry)
        else:
            self._normal_geometry = self.geometry()
            self.state("zoomed")

    def exit_fullscreen(self):
        if self.state() == "zoomed":
            self.state("normal")
            self.geometry(self._normal_geometry)

    def refresh(self):
        if self.rows:
            self.dimension_label = self.rows[0].get("dimension_label", self.dimension_label)
            self.matrix_name_var.set(self.dimension_label)
            self.title(f"{self.identity_label} - {self.dimension_label}")
        self.tree.delete(*self.tree.get_children())
        for index, row in enumerate(self.rows):
            self.tree.insert(
                "",
                "end",
                iid=str(index),
                values=(
                    row.get("label", ""),
                    format_ratio(row.get("ratio", "")),
                    row.get("sub_category", ""),
                    row.get("enabled", "TRUE"),
                    row.get("value_key", ""),
                    row.get("notes", ""),
                ),
            )
        self.app.refresh_matrix_cards()
        self.update_ratio_remaining()

    def on_select(self, _event=None):
        selected = self.tree.selection()
        if not selected:
            return
        self.selected_index = int(selected[0])
        row = self.rows[self.selected_index]
        for key, entry in self.fields.items():
            entry.delete(0, "end")
            entry.insert(0, row.get(key, ""))
        self.update_ratio_remaining()

    def get_field_values(self) -> dict:
        return {key: entry.get().strip() for key, entry in self.fields.items()}

    def rows_with_current_edit(self, values: dict | None = None, include_new: bool = False) -> list[dict]:
        values = values if values is not None else self.get_field_values()
        rows = [dict(row) for row in self.rows]
        if include_new:
            rows.append(values)
        elif self.selected_index is not None and 0 <= self.selected_index < len(rows):
            rows[self.selected_index].update(values)
        return rows

    def update_ratio_remaining(self):
        if not hasattr(self, "ratio_remaining_var"):
            return
        values = self.get_field_values() if hasattr(self, "fields") else {}
        include_new = self.selected_index is None and any(str(value).strip() for value in values.values())
        rows = self.rows_with_current_edit(values, include_new=include_new)
        total = 0.0
        invalid = False
        for row in rows:
            if str(row.get("enabled", "TRUE")).upper() == "FALSE":
                continue
            ratio = parse_ratio(row.get("ratio"))
            if ratio is None:
                invalid = True
                continue
            total += ratio
        remaining = 100.0 - total
        suffix = "（存在未填写/非法占比）" if invalid else ""
        self.ratio_remaining_var.set(f"启用条目占比剩余额度：{format_ratio(remaining)}{suffix}")

    def ensure_manual_ratio_input(self, values: dict) -> bool:
        if str(values.get("enabled", "TRUE")).upper() == "FALSE":
            return True
        ratio_text = values.get("ratio", "").strip()
        if not ratio_text:
            messagebox.showinfo("提示", "启用状态的条目必须填写占比。")
            return False
        ratio = parse_ratio(ratio_text)
        if ratio is None or ratio < 0:
            messagebox.showerror("占比错误", "占比必须是大于等于 0 的 float 数值。")
            return False
        return True

    def validate_ratio_values(self, rows: list[dict]) -> bool:
        error = matrix_ratio_error(rows)
        if error:
            messagebox.showerror("占比错误", f"{self.dimension_label}：{error}\n注意：只统计启用状态的条目。")
            return False
        return True

    def resolve_ratio_values(self, rows: list[dict]) -> bool:
        error = matrix_ratio_error(rows)
        if not error:
            return True
        result = ResizableMessageBox._show(
            "占比校验",
            f"{self.dimension_label}：{error}\n\n请选择处理方式：\n继续编辑：返回弹窗手动调整占比。\n随机占比：系统为启用条目随机生成占比，合计 100%。\n均分占比：系统为启用条目平均分配占比，合计 100%。",
            [("继续编辑", "edit"), ("随机占比", "random"), ("均分占比", "equal")],
            "edit",
            self,
        )
        if result == "random":
            randomize_matrix_ratios(rows)
            return True
        if result == "equal":
            equalize_matrix_ratios(rows)
            return True
        return False

    def clear_ratios(self):
        if not self.rows:
            return
        if not messagebox.askyesno("确认清零", f"确认将「{self.dimension_label}」所有启用条目的占比清零吗？"):
            return
        self.app.prepare_undo("占比清零")
        for row in self.rows:
            if str(row.get("enabled", "TRUE")).upper() != "FALSE":
                row["ratio"] = "0"
        self.selected_index = None
        for entry in self.fields.values():
            entry.delete(0, "end")
        self.app.save_state()
        self.refresh()

    def save_matrix_state(self):
        rows_copy = [dict(row) for row in self.rows]
        if not self.resolve_ratio_values(rows_copy):
            return
        error = matrix_ratio_error(rows_copy)
        if error:
            return
        for current_row, next_row in zip(self.rows, rows_copy):
            current_row["ratio"] = next_row.get("ratio", current_row.get("ratio", ""))
        self.app.save_state()
        self.refresh()
        messagebox.showinfo("保存完成", "已保存到本地。")

    def rename_matrix(self):
        new_name = self.matrix_name_var.get().strip()
        if not new_name:
            messagebox.showinfo("提示", "矩阵名称不能为空。")
            self.matrix_name_var.set(self.dimension_label)
            return
        if new_name == self.dimension_label:
            return
        if not messagebox.askyesno("确认修改", f"确认将矩阵「{self.dimension_label}」改名为「{new_name}」吗？"):
            self.matrix_name_var.set(self.dimension_label)
            return
        self.app.prepare_undo("修改矩阵名称")
        for row in self.rows:
            row["dimension_label"] = new_name
        self.dimension_label = new_name
        self.title(f"{self.identity_label} - {self.dimension_label}")
        self.app.save_state()
        self.refresh()

    def add_row(self):
        values = self.get_field_values()
        if not values["label"]:
            values["label"] = "新选项"
        if not self.ensure_manual_ratio_input(values):
            return
        if not messagebox.askyesno("确认新增", f"确认向「{self.dimension_label}」新增选项「{values['label']}」吗？"):
            return
        self.app.prepare_undo("新增矩阵选项")
        identity_rows = self.app.get_identity_options(self.identity_id)
        sample = self.rows[0] if self.rows else {}
        row = {
            "option_id": f"CUSTOM_{self.identity_id}_{self.dimension_id}_{len(identity_rows) + 1}",
            "dimension_id": self.dimension_id,
            "dimension_label": self.dimension_label,
            "module": sample.get("module", self.app.default_module_for_scope(self.identity_id)),
            "role_scope": sample.get("role_scope", self.identity_id),
            "category": sample.get("category", self.app.default_category_for_scope(self.identity_id)),
            "sub_category": values.get("sub_category", ""),
            "label": values["label"],
            "ratio": format_ratio(parse_ratio(values.get("ratio"))),
            "value_key": values.get("value_key") or f"custom_{self.identity_id}_{self.dimension_id}_{len(identity_rows) + 1}",
            "source_line": "",
            "enabled": values.get("enabled") or "TRUE",
            "notes": values.get("notes") or "GUI新增",
        }
        next_rows = self.rows + [row]
        if not self.resolve_ratio_values(next_rows):
            return
        identity_rows.append(row)
        self.app.save_state()
        self.refresh()

    def update_row(self):
        if self.selected_index is None:
            messagebox.showinfo("提示", "请先选择一条选项。")
            return
        if not messagebox.askyesno("确认修改", f"确认保存当前选项修改到「{self.dimension_label}」吗？"):
            return
        target = self.rows[self.selected_index]
        values = self.get_field_values()
        if not self.ensure_manual_ratio_input(values):
            return
        values["ratio"] = format_ratio(parse_ratio(values.get("ratio")))
        next_rows = [dict(row) for row in self.rows]
        next_rows[self.selected_index].update(values)
        if not self.resolve_ratio_values(next_rows):
            return
        self.app.prepare_undo("修改矩阵选项")
        for current_row, next_row in zip(self.rows, next_rows):
            current_row["ratio"] = next_row.get("ratio", current_row.get("ratio", ""))
        values["ratio"] = next_rows[self.selected_index].get("ratio", values["ratio"])
        target.update(values)
        self.app.save_state()
        self.refresh()

    def delete_row(self):
        if self.selected_index is None:
            messagebox.showinfo("提示", "请先选择一条选项。")
            return
        target = self.rows[self.selected_index]
        if not messagebox.askyesno("确认删除", f"确认删除选项「{target.get('label', '')}」吗？"):
            return
        self.app.prepare_undo("删除矩阵选项")
        identity_rows = self.app.get_identity_options(self.identity_id)
        identity_rows.remove(target)
        normalize_matrix_ratios(self.rows)
        self.selected_index = None
        self.app.save_state()
        self.refresh()

    def export_matrix(self):
        target = filedialog.asksaveasfilename(
            title="导出此矩阵",
            defaultextension=".xlsx",
            initialfile=f"{self.identity_label}_{self.dimension_label}_{datetime.now():%Y%m%d_%H%M}.xlsx",
            filetypes=[("Excel files", "*.xlsx"), ("All files", "*.*")],
        )
        if not target:
            return
        build_xlsx(
            target,
            [
                (
                    self.display_export_sheet_name(),
                    option_rows_to_excel_rows(self.rows, self.identity_id, self.identity_label, "single_matrix"),
                )
            ],
        )
        messagebox.showinfo("导出完成", f"已导出 {len(self.rows)} 项：\n{target}")

    def import_matrix(self):
        source = filedialog.askopenfilename(
            title="导入此矩阵",
            filetypes=[("Excel files", "*.xlsx"), ("All files", "*.*")],
        )
        if not source:
            return
        try:
            worksheets = read_xlsx(source)
        except Exception as exc:
            messagebox.showerror("导入失败", f"无法读取 Excel：{exc}")
            return

        if not worksheets:
            messagebox.showerror("导入失败", "Excel 中没有可读取的工作表。")
            return
        imported_options = excel_rows_to_options(worksheets[0][1])
        options = [
            row
            for row in imported_options
            if not row.get("dimension_id")
            or row.get("dimension_id") == self.dimension_id
            or row.get("dimension_label") == self.dimension_label
        ]
        if imported_options and not options:
            messagebox.showerror("导入失败", f"Excel 中没有匹配「{self.dimension_label}」的矩阵内容。")
            return

        clean_options = []
        for index, row in enumerate(options, start=1):
            if not isinstance(row, dict):
                continue
            new_row = dict(row)
            new_row["dimension_id"] = self.dimension_id
            new_row["dimension_label"] = self.dimension_label
            new_row.setdefault("module", self.app.default_module_for_scope(self.identity_id))
            new_row.setdefault("role_scope", self.identity_id)
            new_row.setdefault("category", self.app.default_category_for_scope(self.identity_id))
            new_row.setdefault("option_id", f"IMPORT_{self.identity_id}_{self.dimension_id}_{index}")
            new_row.setdefault("label", "导入选项")
            new_row.setdefault("value_key", f"import_{self.identity_id}_{self.dimension_id}_{index}")
            new_row.setdefault("enabled", "TRUE")
            new_row.setdefault("ratio", "")
            clean_options.append(new_row)

        if not clean_options:
            messagebox.showerror("导入失败", "没有可导入的选项。")
            return
        if not self.resolve_ratio_values(clean_options):
            return
        if not messagebox.askyesno("确认导入", f"将覆盖当前「{self.dimension_label}」矩阵的 {len(self.rows)} 项，导入 {len(clean_options)} 项。是否继续？"):
            return

        self.app.prepare_undo("导入覆盖矩阵")
        identity_rows = self.app.get_identity_options(self.identity_id)
        identity_rows[:] = [
            row
            for row in identity_rows
            if row.get("dimension_id") != self.dimension_id
            and row.get("dimension_label") != self.dimension_label
        ]
        identity_rows.extend(clean_options)
        self.selected_index = None
        self.app.save_state()
        self.refresh()

    def display_export_sheet_name(self) -> str:
        return f"{self.identity_label}-{self.app.display_dimension_label(self.dimension_label)}"


