                {"key": "content", "label": "画风详情", "type": "text", "height": 6, "list_width": 360},
                {"key": "color_scheme", "label": "色彩方案", "type": "text", "height": 3, "list_width": 220},
                {"key": "character_scheme", "label": "人物方案（外貌/穿着/颜色）", "type": "text", "height": 3, "list_width": 260},
                {"key": "size_params", "label": "尺寸参数", "list_width": 130},
                {"key": "forbidden_items", "label": "禁止项", "type": "text", "height": 3, "list_width": 220},
                {"key": "full_prompt", "label": "完整画风提示词", "type": "text", "height": 8, "readonly": True, "computed": True, "fallback_key": "content", "list_width": 450},
                {"key": "ai_density", "label": "AI实测浓度", "list_width": 120},
