                {"key": "enabled", "label": "是否启用", "type": "bool", "default": True, "true_label": "启用", "false_label": "停用", "list_width": 100},
                {"key": "track", "label": "赛道", "list_width": 120},
                {"key": "recommendation", "label": "推荐等级", "list_width": 120},
                {"key": "note", "label": "备注", "type": "text", "height": 3, "list_width": 220},
