        scale_row("强度", shadow_strength, 0, 100)
        section("光影色彩")
        toggle_row("启用", color_enabled)
        scale_row("亮度", brightness, -100, 100)
        scale_row("对比度", contrast, -100, 100)
        scale_row("饱和度", saturation, -100, 100)
        scale_row("暖色", warmth, -100, 100)
        section("质感")
